Object.assign(window.TEM8_DICTIONARY, {"aspire":{"oxford":{"phon":"əˈspaɪə(r)","pos":"verb","senses":[{"en":"to have a strong desire to achieve or to become something","cn":"渴望（成就）；有志（成为）","ex":{"en":"She aspired to a scientific career.","cn":"她有志于科学事业。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"向往；渴望；有志于","en":"If you aspire to something such as an important job, you have a strong desire to achieve it.","ex":{"en":"...people who aspire to public office","cn":"渴望担任公职的人"}}]},"media":{"uk":"media/uk/aspire__gb_1.mp3","us":"media/us/aspire__us_1.mp3"},"examples":[{"en":"He aspired to be their next leader.","cn":"他渴望成为他们的下一届领导人。"},{"en":"She aspired to a scientific career.","cn":"她有志于科学事业。"}]},"aspirations":{"lemma":"aspiration","media":{"uk":"media/uk/aspiration__gb_1.mp3","us":"media/us/aspiration__us_1.mp3"}},"asset":{"media":{"uk":"media/uk/asset__gb_1.mp3","us":"media/us/asset__us_1.mp3"},"oxford":{"phon":"ˈæset","pos":"noun","senses":[{"en":"a person or thing that is valuable or useful to somebody/something","cn":"有价值的人（或事物）；有用的人（或事物）","ex":{"en":"In his job, patience is an invaluable asset.","cn":"他干的这份工作，耐心是无价之宝。"}},{"en":"a thing of value, especially property, that a person or company owns, which can be used or sold to pay debts","cn":"资产；财产","g":"[usually plural]","ex":{"en":"the net asset value of the company","cn":"公司的资产净值"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"有用的物（或人）；财富","en":"Something or someone that is an asset is considered useful or helps a person or organization to be successful.","ex":{"en":"Her leadership qualities were the greatest asset of the Conservative Party","cn":"她的领导才能是保守党最宝贵的财富。"}},{"pos":"N-PLURAL 复数名词","cn":"资产；财产","en":"The assets of a company or a person are all the things that they own.","ex":{"en":"By the end of 1989 the group had assets of 3.5 billion francs.","cn":"到1989年底该集团拥有的资产达35亿法郎。"}}]},"examples":[{"en":"Her assets include shares in the company and a house in France.","cn":"她的财产包括公司的股份和在法国的一座房子。"},{"en":"In his job, patience is an invaluable asset.","cn":"他干的这份工作，耐心是无价之宝。"}]},"asks":{"lemma":"ask","media":{"uk":"media/uk/ask__gb_1.mp3","us":"media/us/ask__us_1.mp3"}},"aside":{"media":{"uk":"media/uk/aside__gb_1.mp3","us":"media/us/aside__us_1.mp3"},"oxford":{"phon":"əˈsaɪd","pos":"adverb","senses":[{"en":"to one side; out of the way","cn":"到旁边；在旁边","lab":"figurative","ex":{"en":"She pulled the curtain aside.","cn":"她把窗帘拉向一边。"}},{"en":"to be used later","cn":"留；存","ex":{"en":"We set aside some money for repairs.","cn":"我们存了一些钱作为修理费用。"}},{"en":"used to say that except for one thing, something is true","cn":"除…以外","ex":{"en":"Money worries aside, things are going well.","cn":"除了钱令人发愁外，事情进展顺利。"}},{"en":"something that a character in a play says to the audience, but that the other characters on stage are not intended to hear","cn":"旁白","ex":{"en":"Shakespeare’s use of asides and soliloquies","cn":"莎士比亚对旁白和独白的使用"},"pos":"noun"},{"en":"a remark, often made in a low voice, that is not intended to be heard by everyone present","cn":"低声说的话","ex":{"en":"He made several mocking asides about the inadequacy of women.","cn":"他多次嘲笑女性的不足。"},"pos":"noun"},{"en":"a remark that is not directly connected with the main subject that is being discussed","cn":"离题话","ex":{"en":"I mention it only as an aside.","cn":"我只是顺便提及。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"（把…放或移）向一边，到一边","en":"If you move something aside, you move it to one side of you.","ex":{"en":"Sarah closed the book and laid it aside.","cn":"萨拉合上书，把它放在了一边。"}},{"pos":"ADV 副词","cn":"（把…带或拉）到一边","en":"If you take or draw someone aside, you take them a little way away from a group of people in order to talk to them in private.","ex":{"en":"Billy Ewing grabbed him by the elbow and took him aside","cn":"比利·尤因拉着他的胳膊肘把他带到了一边。"}},{"pos":"ADV 副词","cn":"向旁边;向一旁","en":"If you move aside, you get out of someone's way.","ex":{"en":"She had been standing in the doorway, but now she stepped aside to let them pass.","cn":"她一直在门口站着，但是现在闪到了一边，让他们过去了。"}},{"pos":"ADV 副词","cn":"留出;空出;攒下来","en":"If you set something such as time, money, or space aside for a particular purpose, you save it and do not use it for anything else.","ex":{"en":"She wants to put her pocket-money aside for holidays.","cn":"她想把零花钱攒起来用于度假。"}},{"pos":"ADV 副词","cn":"不理;不顾;置之一边地","en":"If you brush or sweep aside a feeling or suggestion, you reject it.","ex":{"en":"Talk to a friend who will really listen and not brush aside your feelings","cn":"和一个能真正倾听你诉说并重视你感受的朋友谈谈。"}},{"pos":"ADV 副词","cn":"（谈话中）撇开…不谈","en":"You use aside to indicate that you have finished talking about something, or that you are leaving it out of your discussion, and that you are about to talk about something else.","ex":{"en":"Leaving aside the tiny minority who are clinically depressed, most people who have bad moods also have very good moods","cn":"撇开极少数临床抑郁症患者不谈，大多数情绪低落的人也有心情非常愉快的时候。"}},{"pos":"N-COUNT 可数名词","cn":"（戏剧中的）旁白","en":"An aside is a comment that a character in a play makes to the audience, which the other characters are supposed not to be able to hear.","ex":{"en":"Exasperated with her children, she rolls her eyes and mutters an aside to the camera, 'No wonder I drink!'","cn":"在被她的孩子们激怒后，她翻了一下白眼对着镜头嘀咕道，“难怪我会酗酒！”"}},{"pos":"N-COUNT 可数名词","cn":"题外话；插入语","en":"An aside is something that you say that is not directly connected with what you are talking about.","ex":{"en":"The pace of the book is leisurely, with enjoyable literary and historical asides.","cn":"这本书节奏明快，另外还穿插了一些趣味盎然的文史掌故。"}},{"pos":"PREP-PHRASE 短语介词","cn":"同apart from（通常用于美国英语）","en":"Aside from means the same as apart from. This form is more usual in American English."}]},"examples":[{"en":"( figurative ) Leaving aside (= not considering at this stage) the cost of the scheme, let us examine its benefits.","cn":"方案的费用暂且不理，咱们来审查方案的好处。"},{"en":"Money worries aside, things are going well.","cn":"除了钱令人发愁外，事情进展顺利。"}]},"asleep":{"media":{"uk":"media/uk/asleep__gb_1.mp3","us":"media/us/asleep__us_1.mp3"},"oxford":{"phon":"əˈsliːp","pos":"adjective","senses":[{"en":"sleeping","cn":"睡着","ex":{"en":"I waited until they were all fast asleep (= sleeping deeply).","cn":"我一直等到他们都进入了梦乡。"}},{"en":"used to describe a part of the body that has no feeling in it, usually because it has been in the same position for too long","cn":"麻木的","ex":{"en":"I couldn't move straight away, as my leg was completely asleep.","cn":"我不能马上移动，因为我的腿完全麻木了。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"睡着的；熟睡的","en":"Someone who is asleep is sleeping.","ex":{"en":"My four year-old daughter was asleep on the sofa.","cn":"我4岁的女儿在沙发上睡着了。"}},{"pos":"PHRASE 短语","cn":"入睡；睡着；进入梦乡","en":"When you fall asleep, you start sleeping.","ex":{"en":"Sam snuggled down in his pillow and fell asleep.","cn":"萨姆舒服地枕着枕头进入了梦乡。"}},{"pos":"PHRASE 短语","cn":"熟睡的；酣睡的","en":"Someone who is fast asleep or sound asleep is sleeping deeply.","ex":{"en":"They were both fast asleep in their cots","cn":"他们俩在婴儿床上酣睡着。"}}]},"examples":[{"en":"He was so exhausted that he fell asleep at his desk.","cn":"他太累了，竟伏在书桌上睡着了。"},{"en":"She was still half asleep (= not fully awake) when she arrived at work.","cn":"她到了上班地点时仍然睡眼惺忪。"}]},"asylum":{"oxford":{"phon":"əˈsaɪləm","pos":"noun","senses":[{"en":"protection that a government gives to people who have left their own country, usually because they were in danger for political reasons","cn":"（政治）庇护，避难","g":"[uncountable]","lab":"formal","ex":{"en":"to seek/apply for/be granted asylum","cn":"寻求／申请／获准政治避难"}},{"en":"a hospital where people who were mentally ill could be cared for, often for a long time","cn":"精神病院","g":"[countable]","lab":"old use"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（通常指政治）庇护，避难","en":"If a government gives a person from another country asylum, they allow them to stay, usually because they are unable to return home safely for political reasons.","ex":{"en":"He applied for asylum in 1987 after fleeing the police back home.","cn":"1987年他在本国逃脱警察追捕后，就申请了政治庇护。"}},{"pos":"N-COUNT 可数名词","cn":"精神病院","en":"An asylum is a psychiatric hospital."}]},"media":{"uk":"media/uk/asylum__gb_1.mp3","us":"media/us/asylum__us_1.mp3"},"examples":[{"en":"There was a nationwide debate on whether the asylum laws should be changed.","cn":"对是否应该修改政治避难法展开了一场全国性的大辩论。"},{"en":"to seek/apply for/be granted asylum","cn":"寻求/申请/获准政治避难"}]},"assess":{"oxford":{"phon":"əˈses","pos":"verb","senses":[{"en":"to make a judgement about the nature or quality of somebody/something","cn":"评估，评定（性质、质量）","ex":{"en":"Accurately assessing environmental impacts is very complex.","cn":"准确评估环境影响是非常复杂的。"}},{"en":"to calculate the amount or value of something","cn":"估算，估定，核定（数量、价值）","ex":{"en":"They have assessed the amount of compensation to be paid.","cn":"他们已经核定赔偿额。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"评估；评价；考查","en":"When you assess a person, thing, or situation, you consider them in order to make a judgment about them.","ex":{"en":"Our correspondent has been assessing the impact of the sanctions","cn":"我们的记者一直在评估制裁带来的影响。"}},{"pos":"VERB 动词","cn":"评估（价值）；估价","en":"When you assess the amount of money that something is worth or should be paid, you calculate or estimate it.","ex":{"en":"Ask them to send you information on how to assess the value of your belongings","cn":"让他们把怎样评估你的财产价值的资料寄来。"}}]},"media":{"uk":"media/uk/assess__gb_1.mp3","us":"media/us/assess__us_1.mp3"},"examples":[{"en":"The young men were assessed as either safe or unsafe drivers.","cn":"这些年轻人被评定为谨慎驾驶员和不谨慎驾驶员两类。"},{"en":"We are trying to assess how well the system works.","cn":"我们正设法评估这个系统运行得是否顺畅。"}]},"assistant":{"oxford":{"phon":"əˈsɪstənt","pos":"noun","senses":[{"en":"a person who helps or supports somebody, usually in their job","cn":"助理；助手","ex":{"en":"My assistant will now demonstrate the machine in action.","cn":"现在我的助手将演示机器运转情况。"}},{"en":"a person whose job is to serve customers in a shop","cn":"店员；售货员","lab":"both British English","ex":{"en":"an assistant in a department store","cn":"一名百货公司售货员"}},{"en":"a student at university or college who spends time in a foreign country teaching his or her own language in a school","cn":"助教（在国外留学的大学生，教授本国语）","lab":"British English"},{"en":"having a rank below that of a senior person and helping them in their work","cn":"助理的；副的","ex":{"en":"the assistant manager/director/commissioner","cn":"副经理；副总裁；助理专员"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（用于头衔或职务前，表示级别略低）助理的，副的","en":"Assistant is used in front of titles or jobs to indicate a slightly lower rank. For example, an assistant director is one rank lower than a director in an organization.","ex":{"en":"...the Assistant Secretary of Defense.","cn":"助理国防部长"}},{"pos":"N-COUNT 可数名词","cn":"助手;助理;副手","en":"Someone's assistant is a person who helps them in their work.","ex":{"en":"Kalan called his assistant, Hashim, to take over while he went out","cn":"考兰叫助理哈希姆在自己外出时代理其职。"}},{"pos":"N-COUNT 可数名词","cn":"店员；售货员","en":"An assistant is a person who works in a shop selling things to customers.","ex":{"en":"The assistant took the book and checked the price on the back cover","cn":"店员拿起书，核对了一下封底的定价。"}}]},"media":{"uk":"media/uk/assistant__gb_1.mp3","us":"media/us/assistant__us_1.mp3"},"examples":[{"en":"My assistant will now demonstrate the machine in action.","cn":"现在我的助手将演示机器运转情况。"},{"en":"a sales assistant in a department store","cn":"一名百货公司售货员"}]},"as":{"media":{"uk":"media/uk/as_1_gb_1.mp3","us":"media/us/as_1_us_1.mp3"},"oxford":{"phon":"əz","pos":"preposition","senses":[{"en":"used to describe somebody/something appearing to be somebody/something else","cn":"像；如同","ex":{"en":"They were all dressed as clowns.","cn":"他们都打扮成小丑。"}},{"en":"used to describe the fact that somebody/something has a particular job or function","cn":"作为；当作","ex":{"en":"She works as a courier.","cn":"她的职业是导游。"}},{"en":"used when you are comparing two people or things, or two situations","cn":"（比较时用）像…一样，如同","ex":{"en":"You're as tall as your father.","cn":"你和你父亲一样高。"},"pos":"adverb"},{"en":"used to say that something happens in the same way","cn":"（指事情以同样的方式发生）和…一样","ex":{"en":"As always, he said little.","cn":"他和平时一样，少言寡语。"},"pos":"adverb"},{"en":"used to emphasize an amount","cn":"（强调数量）达到","ex":{"en":"As many as 2 million people could be affected.","cn":"多达 200 万人可能会受到影响。"},"pos":"adverb"},{"en":"while something else is happening","cn":"当…时；随着","ex":{"en":"He sat watching her as she got ready.","cn":"他一直坐着看她准备停当。"},"pos":"conjunction"},{"en":"in the way in which","cn":"照…方式","ex":{"en":"They did as I had asked.","cn":"他们是按照我的要求做的。"},"pos":"conjunction"},{"en":"used to state the reason for something","cn":"因为；由于","ex":{"en":"As you were out, I left a message.","cn":"你不在，所以我留了一张字条儿。"},"pos":"conjunction"},{"en":"used to make a comment or to add information about what you have just said","cn":"正如；如同","ex":{"en":"As you know, Julia is leaving soon.","cn":"你是知道的，朱莉娅马上要离开了。"},"pos":"conjunction"},{"en":"used to say that although something is true, what follows is also true","cn":"尽管；虽然；即使","ex":{"en":"Happy as they were, there was something missing.","cn":"尽管他们很快乐，但总缺少点什么。"},"pos":"conjunction"}]},"collins":{"senses":[{"pos":"CONJ-SUBORD 连词","cn":"（表示两件事情同时发生）当…的时候，在…的同时","en":"If something happens as something else happens, it happens at the same time.","ex":{"en":"Another policeman has been injured as fighting continued this morning","cn":"今早又有一名警员在冲突中受伤。"}},{"pos":"PHR-CONJ-COORD","cn":"像…一样","en":"You use the structure as...as when you are comparing things.","ex":{"en":"I never went through a final exam that was as difficult as that one","cn":"我从来没有碰到过像那次那么难的期末考试。"}},{"pos":"PHR-CONJ-COORD","cn":"（强调数量）多达，只有","en":"You use as...as to emphasize amounts of something.","ex":{"en":"You can look forward to a significant cash return by saving from as little as £10 a month","cn":"只要每个月存下区区10英镑，你就有希望得到相当可观的现金收益。"}},{"pos":"PREP 介词","cn":"作为；当作","en":"You use as when you are indicating what someone or something is or is thought to be, or what function they have.","ex":{"en":"He has worked as a diplomat in the US, Sudan and Saudi Arabia","cn":"他曾任驻美国、苏丹和沙特阿拉伯的外交官。"}},{"pos":"PREP 介词","cn":"还是…的时候","en":"If you do something as a child or as a teenager, for example, you do it when you are a child or a teenager.","ex":{"en":"She loved singing as a child and started vocal training at 12.","cn":"她从小就喜欢唱歌，12岁开始了声乐训练。"}},{"pos":"CONJ-SUBORD 连词","cn":"同样地；一样地；像…一样","en":"You use as to say how something happens or is done, or to indicate that something happens or is done in the same way as something else.","ex":{"en":"I'll behave toward them as I would like to be treated","cn":"我会以希望别人对待我的方式来对待他们。"}},{"pos":"PREP 介词","cn":"因为;作为（结果）","en":"You use as in expressions like as a result and as a consequence to indicate how two situations or events are related to each other.","ex":{"en":"As a result of the growing fears about home security, more people are arranging for someone to stay in their home when they're away","cn":"因为越来越担心住宅安全，更多的人在出门的时候会在家中留人。"}},{"pos":"CONJ-SUBORD 连词","cn":"（引导短从句）正如，就像","en":"You use as to introduce short clauses which comment on the truth of what you are saying.","ex":{"en":"As you can see, we're still working","cn":"如你所见，我们仍在工作。"}},{"pos":"CONJ-SUBORD 连词","cn":"因为；由于","en":"You can use as to mean 'because' when you are explaining the reason for something.","ex":{"en":"They are regularly sent booklets about personal safety, but they barely read them as they have so much paperwork to deal with","cn":"他们经常会收到关于人身安全问题的宣传册，但因为大量文案工作缠身，他们几乎无暇阅读。"}},{"pos":"PHRASE 短语","cn":"可以说;在某种程度上","en":"You say as it were in order to make what you are saying sound less definite.","ex":{"en":"I'd understood the words, but I didn't, as it were, understand the question.","cn":"字面的意思我懂了，但是可以说我并不能理解这个问题。"}},{"pos":"PHRASE 短语","cn":"事实上，实际上（表示实际情况和可能情况的对比）","en":"You use expressions such as as it is ,as it turns out, and as things stand when you are making a contrast between a possible situation and what actually happened or is the case.","ex":{"en":"I want to work at home on a Tuesday but as it turns out sometimes it's a Wednesday or a Thursday.","cn":"我想周二在家工作，但实际上有时却是周三或是周四。"}},{"pos":"","cn":"","en":"as against→see: ; as ever→see: ; as a matter of fact→see: ; as follows→see: ; as long as→see: ; as opposed to→see: ; as regards→see: ; as soon as→see: ; as such→see: ; as well→see: ; as well as→see: ; as yet→see: ;"},{"pos":"PREP-PHRASE 短语介词","cn":"至于…","en":"You use as for and as to at the beginning of a sentence in order to introduce a slightly different subject that is still connected to the previous one.","ex":{"en":"I feel that there's a lot of pressure put on policemen. And as for putting guns in their hands, I don't think that's a very good idea at all.","cn":"我觉得给警员的压力太大了。至于让他们佩枪，我并不认为是一个明智之举。"}},{"pos":"PREP-PHRASE 短语介词","cn":"关于…","en":"You use as to to indicate what something refers to.","ex":{"en":"They should make decisions as to whether the student needs more help","cn":"他们应该决定学生是否需要更多的帮助。"}},{"pos":"PREP-PHRASE 短语介词","cn":"在…时；从…起；自…始","en":"If you say that something will happen as of, or in British English as from, a particular date or time, you mean that it will happen from that time on.","ex":{"en":"The border, effectively closed since 1981, will be opened as of January the 1st","cn":"实质上从1981年就已关闭的边境将于1月1日开放。"}},{"pos":"PHR-CONJ-SUBORD","cn":"好像；仿佛","en":"You use as if and as though when you are giving a possible explanation for something or saying that something appears to be the case when it is not.","ex":{"en":"Anne shrugged, as if she didn't know","cn":"安妮耸了耸肩，好像她并不知晓。"}}]},"examples":[{"en":"They got 27% of the vote as against 32% at the last election.","cn":"这次选举他们得了 27% 的票，而上次他们得了 32%。"},{"en":"Teachers must put the brakes on, as it were, when they notice students looking puzzled.","cn":"当老师发现学生神色茫然时，就应该在一定程度上放慢速度。"}]},"ascribe":{"media":{"uk":"media/uk/ascribe__gb_1.mp3","us":"media/us/ascribe__us_1.mp3"},"oxford":{"phon":"əˈskraɪb","pos":"verb","senses":[{"en":"to consider or state that a book, etc. was written by a particular person","cn":"认为 … 是（某人）所写"},{"en":"to consider that sth is caused by a particular thing or person","cn":"把 … 归因于；认为 … 是由于"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"把…归因于；把…归咎于","en":"If you ascribe an event or condition to a particular cause, you say or consider that it was caused by that thing.","ex":{"en":"An autopsy eventually ascribed the baby's death to sudden infant death syndrome.","cn":"尸检最终认定孩子死于婴儿猝死综合征。"}},{"pos":"VERB 动词","cn":"认为是…的特点;认为…具有","en":"If you ascribe a quality to someone, you consider that they possess it.","ex":{"en":"We do not ascribe a superior wisdom to government or the state.","cn":"我们并不认为政府或是国家有超凡的智慧。"}},{"pos":"VERB 动词","cn":"认为…是…所说（或所为）","en":"If you ascribe something such as a quotation or a work of art to someone, you say that they said it or created it.","ex":{"en":"He mistakenly ascribes the expression 'survival of the fittest' to Charles Darwin.","cn":"他错误地认为“适者生存”是查尔斯·达尔文说的。"}}]},"examples":[{"en":"This play is usually ascribed to Shakespeare.","cn":"通常认为这部剧是莎士比亚所写。"},{"en":"He ascribed his failure to bad luck.","cn":"他认为自己的失败是运气不好。"}]},"associated":{"media":{"uk":"media/uk/associated__gb_1.mp3","us":"media/us/associated__us_1.mp3"},"oxford":{"phon":"əˈsəʊsieɪtɪd","pos":"adjective","senses":[{"en":"if one thing is associated with another, the two things are connected because they happen together or one thing causes the other","cn":"有关联的；相关的","ex":{"en":"the risks associated with taking drugs","cn":"与吸毒有关的危险"}},{"en":"if a person is associated with an organization, etc. they support it","cn":"有联系的","ex":{"en":"He no longer wished to be associated with the party's policy on education.","cn":"他不再愿意认同该党的教育方针。"}},{"en":"used in the name of a business company that is made up of a number of smaller companies","cn":"（用于联合企业的名称）联合的","ex":{"en":"Associated Newspapers","cn":"联合报业"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(与…）相关的；相联系的","en":"If one thing is associated with another, the two things are connected with each other.","ex":{"en":"These symptoms are particularly associated with migraine headaches.","cn":"这些症状尤其与偏头痛相关。"}},{"pos":"ADJ 形容词","cn":"（用于公司名称）联合的，联营的","en":"Associated is used in the name of a company that is made up of a number of smaller companies which have joined together.","ex":{"en":"...the Associated Press.","cn":"美联社"}}]},"examples":[{"en":"He no longer wished to be associated with the party's policy on education.","cn":"他不再愿意与该党的教育方针认同。"},{"en":"Salaries and associated costs have risen substantially.","cn":"薪金与相关费用大大增加。"}],"base":"associate"},"assigns":{"lemma":"assign"},"ascending":{"lemma":"ascend"},"astonished":{"media":{"uk":"media/uk/astonished__gb_1.mp3","us":"media/us/astonished__us_1.mp3"},"oxford":{"phon":"əˈstɒnɪʃt","pos":"adjective","senses":[{"en":"very surprised","cn":"感到十分惊讶；吃惊","ex":{"en":"The helicopter landed before our astonished eyes.","cn":"直升机就降落在我们眼前，令人十分惊讶。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"感到惊讶的;十分惊奇的","en":"If you are astonished by something, you are very surprised about it.","ex":{"en":"I was astonished by his stupidity","cn":"他的愚笨让我大跌眼镜。"}}]},"examples":[{"en":"The helicopter landed before our astonished eyes.","cn":"直升机就降落在我们眼前，令人十分惊讶。"},{"en":"My parents looked astonished at my news.","cn":"我的父母听到我的消息后显得十分惊讶。"}]},"assumption":{"media":{"uk":"media/uk/assumption__gb_1.mp3","us":"media/us/assumption__us_1.mp3"},"oxford":{"phon":"əˈsʌmpʃn","pos":"noun","senses":[{"en":"a belief or feeling that something is true or that something will happen, although there is no proof","cn":"假定；假设","g":"[countable]","ex":{"en":"an underlying/implicit assumption","cn":"暗含的假定"}},{"en":"the act of taking or beginning to have power or responsibility","cn":"（责任的）承担；担任；（权力的）获得","g":"[countable, uncountable]","lab":"formal","ex":{"en":"their assumption of power/control","cn":"他们权力／控制的取得"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"假定;假设;臆断","en":"If you make an assumption that something is true or will happen, you accept that it is true or will happen, often without any real proof.","ex":{"en":"They have taken a wrong turning in their assumption that all men and women think alike","cn":"他们错误地设想所有男女均见解一致。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（权力的）取得；（责任的）承担","en":"Someone's assumption of power or responsibility is their taking of it.","ex":{"en":"The government have retained the support which greeted their assumption of power last March.","cn":"自从在刚过去的三月掌权以来，政府的支持率依旧未减。"}}]},"examples":[{"en":"We are working on the assumption that everyone invited will turn up.","cn":"我们假定了每一个人都会应邀出席并正就此作出安排。"},{"en":"We need to challenge some of the basic assumptions of Western philosophy.","cn":"我们有必要向西方哲学的某些基本假设提出质疑。"}]},"assume":{"media":{"uk":"media/uk/assume__gb_1.mp3","us":"media/us/assume__us_1.mp3"},"oxford":{"phon":"əˈsjuːm","pos":"verb","senses":[{"en":"to think or accept that something is true but without having proof of it","cn":"假定；假设；认为","ex":{"en":"It is reasonable to assume (that) the economy will continue to improve.","cn":"认为经济将继续好转是有道理的。"}},{"en":"to take or begin to have power or responsibility","cn":"承担（责任）；就（职）；取得（权力）","lab":"formal","ex":{"en":"Rebel forces have assumed control of the capital.","cn":"反叛武装力量已控制了首都。"}},{"en":"to begin to have a particular quality or appearance","cn":"呈现（外观、样子）；显露（特征）","lab":"formal","ex":{"en":"This matter has assumed considerable importance.","cn":"这件事看来相当重要。"}},{"en":"to pretend to have a particular feeling or quality","cn":"装出；假装","lab":"formal","ex":{"en":"He assumed an air of concern.","cn":"他装出关心的样子。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"假定;以为;假设","en":"If you assume that something is true, you imagine that it is true, sometimes wrongly.","ex":{"en":"It is a misconception to assume that the two continents are similar","cn":"关于这两块大陆相似的假设是一种误解。"}},{"pos":"VERB 动词","cn":"掌管，夺取，取得（权力）；承担（责任）","en":"If someone assumes power or responsibility, they take power or responsibility.","ex":{"en":"Mr Cross will assume the role of Chief Executive with a team of four directors","cn":"克劳斯先生将出任首席执行官，手下有4位经理。"}},{"pos":"VERB 动词","cn":"呈现，具有，显露（某种特质）","en":"If something assumes a particular quality, it begins to have that quality.","ex":{"en":"In his dreams, the mountains assumed enormous importance.","cn":"在他的梦中，山有着至关重要的作用。"}},{"pos":"VERB 动词","cn":"表现出（某种表情）；装出，做出（某种样子）","en":"If you assume a particular expression or way of behaving, you start to look or behave in this way.","ex":{"en":"He contented himself by assuming an air of superiority","cn":"他表现出一副高高在上的样子以获得自我满足。"}},{"pos":"PHRASE 短语","cn":"让我们假设；姑且假设","en":"You can use let us assume or let's assume when you are considering a possible situation or event, so that you can think about the consequences.","ex":{"en":"Let us assume those clubs actually win something. Then players will receive large bonuses","cn":"倘若那些俱乐部真的赚了，那么球员就会获得一大笔奖金。"}}]},"examples":[{"en":"In this example we have assumed a unit price of $10.","cn":"在这个例子中，我们已假定单价为 10 元。"},{"en":"The court assumed responsibility for the girl's welfare.","cn":"法庭承担了保障这个女孩福利的责任。"}]},"association":{"media":{"uk":"media/uk/association__gb_1.mp3","us":"media/us/association__us_1.mp3"},"oxford":{"phon":"əˌsəʊsiˈeɪʃn","pos":"noun","senses":[{"en":"an official group of people who have joined together for a particular purpose","cn":"协会；社团；联盟","g":"[countable + singular or plural verb]","lab":"especially in North American English","ex":{"en":"Do you belong to any professional or trade associations?","cn":"你参加了专业学会或行业协会没有？"}},{"en":"a connection or relationship between people or organizations","cn":"联合；合伙；关联；交往","g":"[countable, uncountable]","ex":{"en":"They have maintained a close association with a college in the US.","cn":"他们和美国一所学院保持了密切联系。"}},{"en":"an idea or a memory that is suggested by somebody/something; a mental connection between ideas","cn":"联想；联系","g":"[countable, usually plural]","ex":{"en":"The seaside had all sorts of pleasant associations with childhood holidays for me.","cn":"海滨使我联想起童年假期的各种愉快情景。"}},{"en":"a connection between things where one is caused by the other","cn":"因果关系","g":"[countable, uncountable]","ex":{"en":"Studies have shown strong associations between housing conditions and health.","cn":"研究表明居住条件和健康有密切的关系。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"团体；协会；社团","en":"An association is an official group of people who have the same job, aim, or interest.","ex":{"en":"...the British Olympic Association","cn":"英国奥林匹克协会"}},{"pos":"N-COUNT 可数名词","cn":"关联；交往","en":"Your association with a person or a thing such as an organization is the connection that you have with them.","ex":{"en":"...the company's six-year association with retailer J.C. Penney Co","cn":"该公司与零售商 J. C. 彭尼公司6年的业务往来"}},{"pos":"N-COUNT 可数名词","cn":"联想","en":"If something has particular associations for you, it is connected in your mind with a particular memory, idea, or feeling.","ex":{"en":"He has a shelf full of things, each of which has associations for him","cn":"他的一个搁架上摆满了东西，每一样都能勾起他许多回忆。"}},{"pos":"PHRASE 短语","cn":"与…联合;与…合作","en":"If you do something in association with someone else, you do it together.","ex":{"en":"Published in association with the Council for the Protection of Rural England, the book provides refreshing solutions to the long-term problem of water conservation.","cn":"这本书与英格兰乡村保护委员会合作出版，就节约水资源这个长期问题提供了全新的解决方法。"}},{"pos":"PHRASE 短语","cn":"（事物）与…在一起","en":"If one thing is found in association with another, they are found together."}]},"examples":[{"en":"The book was published in association with (= together with) English Heritage.","cn":"这本书是与英国文化遗产保护协会联合出版的。"},{"en":"The seaside had all sorts of pleasant associations with childhood holidays for me.","cn":"海滨使我联想起童年假期的各种愉快情景。"}]},"assembly":{"oxford":{"phon":"əˈsembli","pos":"noun","senses":[{"en":"a group of people who have been elected to meet together regularly and make decisions or laws for a particular region or country","cn":"立法机构；会议；议会","g":"[countable]","ex":{"en":"state/legislative/federal/local assemblies","cn":"州众议院；立法会议；联邦／地方议会"}},{"en":"the meeting together of a group of people for a particular purpose; a group of people who meet together for a particular purpose","cn":"集会；（统称）集会者","g":"[uncountable, countable]","ex":{"en":"They were fighting for freedom of speech and freedom of assembly.","cn":"他们为言论自由和集会自由而斗争。"}},{"en":"a meeting of the teachers and students in a school, usually at the start of the day, to give information, discuss school events or say prayers together","cn":"（全校师生的）晨会，朝会","g":"[countable, uncountable]","ex":{"en":"The deputy head was taking (= leading) school assembly that day.","cn":"副校长正在主持那天的晨会。"}},{"en":"the process of putting together the parts of something such as a vehicle or piece of furniture","cn":"装配；组装；总成","g":"[uncountable]","ex":{"en":"Putting the bookcase together should be a simple assembly job.","cn":"组装书橱应该是个简单的装配活。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"议会；代表大会","en":"An assembly is a large group of people who meet regularly to make decisions or laws for a particular region or country.","ex":{"en":"...the campaign for the first free election to the National Assembly.","cn":"呼吁国民议会召开首次自由选举的运动"}},{"pos":"N-COUNT 可数名词","cn":"集会;集会者","en":"An assembly is a group of people gathered together for a particular purpose.","ex":{"en":"...an assembly of women Olympic gold-medal winners","cn":"奥林匹克金牌女性获得者的集会"}},{"pos":"N-UNCOUNT 不可数名词","cn":"集会（权利）","en":"When you refer to rights of assembly or restrictions on assembly, you are referring to the legal right that people have to gather together.","ex":{"en":"The US Constitution guarantees free speech, freedom of assembly and equal protection","cn":"美国宪法保证言论自由、集会自由和受到平等保护的权利。"}},{"pos":"N-VAR 可变名词","cn":"（全校师生的）晨会，早会","en":"In a school, assembly is a gathering of all the teachers and pupils at the beginning of every school day.","ex":{"en":"By 9, the juniors are in the hall for assembly.","cn":"到9点时，三年级学生都在大厅里等待参加晨会。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"装配；组装","en":"The assembly of a machine, device, or object is the process of fitting its different parts together.","ex":{"en":"For the rest of the day, he worked on the assembly of an explosive device.","cn":"在那天余下的时间里，他继续组装爆炸装置。"}}]},"media":{"uk":"media/uk/assembly__gb_1.mp3","us":"media/us/assembly__us_1.mp3"},"examples":[{"en":"He was to address a public assembly on the issue.","cn":"他要对公众集会发表演说谈论这个问题。"},{"en":"They were fighting for freedom of speech and freedom of assembly.","cn":"他们为言论自由和集会自由而斗争。"}]},"ask":{"media":{"uk":"media/uk/ask__gb_1.mp3","us":"media/us/ask__us_1.mp3"},"oxford":{"phon":"ɑːsk","pos":"verb","senses":[{"en":"to say or write something in the form of a question, in order to get information","cn":"问；询问","g":"[intransitive, transitive]","sc":"question","ex":{"en":"How old are you—if you don’t mind me/my asking?","cn":"要是你不介意我提问，你多大年纪了？"}},{"en":"to tell somebody that you would like them to do something or that you would like something to happen","cn":"要求；请求","g":"[transitive]","lab":"formal","sc":"request","ex":{"en":"Anyone with information is asked to contact the police.","cn":"如有知情者请与警方联系。"}},{"en":"to say that you would like somebody to give you something","cn":"请求，恳求（给予）；征求","g":"[intransitive, transitive]","sc":"request","ex":{"en":"Don't be afraid to ask for help.","cn":"不要害怕求助。"}},{"en":"to request permission to do something","cn":"请求允许；要求准许","g":"[transitive]","sc":"permission","ex":{"en":"I immediately asked to speak to a supervisor.","cn":"我立刻要求与主管谈话。"}},{"en":"to invite somebody","cn":"请；邀请","g":"[transitive]","lab":"informal or North American English","sc":"invite","ex":{"en":"They've asked me to dinner.","cn":"他们已邀请我吃饭。"}},{"en":"to request a particular amount of money for something that you are selling","cn":"要价；索价","g":"[transitive]","sc":"money","ex":{"en":"He's asking £2 000 for the car.","cn":"这辆轿车他要价 2 000 英镑。"}},{"en":"to expect or demand something","cn":"期望；要求","g":"[transitive]","sc":"expect/demand","ex":{"en":"I know I'm asking a great deal.","cn":"我知道我的要求很高。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"问；询问","en":"If you ask someone something, you say something to them in the form of a question because you want to know the answer.","ex":{"en":"'How is Frank?' he asked","cn":"“弗兰克怎么样了？”他问道。"}},{"pos":"VERB 动词","cn":"要求…（做…）；请求…（做…）","en":"If you ask someone to do something, you tell them that you want them to do it.","ex":{"en":"We had to ask him to leave","cn":"我们不得不要求他离开。"}},{"pos":"VERB 动词","cn":"要求（做…）；请求（做…）","en":"If you ask to do something, you tell someone that you want to do it.","ex":{"en":"I asked to see the Director.","cn":"我要求见主任。"}},{"pos":"VERB 动词","cn":"索要;请求，恳求（给予）","en":"If you ask for something, you say that you would like it.","ex":{"en":"I decided to go to the next house and ask for food","cn":"我决定去隔壁那家要点吃的。"}},{"pos":"VERB 动词","cn":"求见","en":"If you ask for someone, you say that you would like to speak to them.","ex":{"en":"There's a man at the gate asking for you.","cn":"门口有个人想见你。"}},{"pos":"VERB 动词","cn":"请求，征求（许可、意见、谅解）","en":"If you ask someone's permission, opinion, or forgiveness, you try to obtain it by putting a request to them.","ex":{"en":"Please ask permission from whoever pays the phone bill before making your call.","cn":"打电话前请先征得话费支付方的同意。"}},{"pos":"VERB 动词","cn":"邀请;约请","en":"If you ask someone to an event or place, you invite them to go there.","ex":{"en":"Couldn't you ask Jon to the party?","cn":"你不能邀请乔恩参加聚会吗？"}},{"pos":"VERB 动词","cn":"要（价）；索（价）","en":"If someone is asking a particular price for something, they are selling it for that price.","ex":{"en":"Mr Pantelaras was asking £6,000 for his collection.","cn":"潘特莱拉斯先生为他的藏品要价6,000英镑。"}},{"pos":"CONVENTION 惯用语","cn":"（通常用于表示对询问感到恼怒或惊讶）不要问我","en":"You reply 'don't ask me' when you do not know the answer to a question, usually when you are annoyed or surprised that you have been asked.","ex":{"en":"'She's got other things on her mind, wouldn't you think?' 'Don't ask me,' murmured Chris. 'I've never met her.'","cn":"“她还有别的心事，你不觉得吗？”“别问我，”克里斯嘀咕道，“我从未见过她。”"}},{"pos":"PHRASE 短语","cn":"只要开口（便可得到）；唾手可得","en":"If something is yours for the asking, you could get it very easily if you wanted to.","ex":{"en":"He knew the nomination was his for the asking.","cn":"他知道只要他开口就能得到那项提名。"}},{"pos":"EXCLAM 感叹语","cn":"（强调反对）请问，真是，这还了得","en":"If you say 'I ask you', you are emphasizing how much you disapprove of someone or something.","ex":{"en":"That silly old bat. I ask you, who'd she think she was?","cn":"那个老蠢货。我倒要问一问，她以为她是谁呀？"}},{"pos":"PHRASE 短语","cn":"（一种正式的询问方式，表示感到困扰或心生疑虑）请问","en":"You can say 'may I ask' as a formal way of asking a question, which shows you are annoyed or suspicious about something.","ex":{"en":"May I ask where you're going, sir?","cn":"先生，请问您要去哪？"}},{"pos":"PHRASE 短语","cn":"依我看；我认为","en":"You can say 'if you ask me' to emphasize that you are stating your personal opinion.","ex":{"en":"He was nuts, if you ask me.","cn":"要我说的话，他是个疯子。"}},{"pos":"PHRASE 短语","cn":"自找麻烦；自讨苦吃","en":"If you say that someone is asking for trouble or is asking for it, you mean that they are behaving in a way that makes it very likely that they will get into trouble.","ex":{"en":"To go ahead with the match after such clear advice had been asking for trouble.","cn":"都劝说得这么明白了还要继续比赛，这简直就是自讨苦吃。"}},{"pos":"","cn":"","en":"相关词组：ask after ask around"}]},"examples":[{"en":"I don't know of any vacancies in the company but I'll ask around.","cn":"我不知道公司有没有空缺，不过我会打听打听。"},{"en":"I know it's asking a lot to expect them to win again.","cn":"我知道期望他们再次获胜未免要求太高了。"}]},"assistance":{"media":{"uk":"media/uk/assistance__gb_1.mp3","us":"media/us/assistance__us_1.mp3"},"oxford":{"phon":"əˈsɪstəns","pos":"noun","senses":[{"en":"help or support","cn":"帮助；援助；支持","ex":{"en":"technical/economic/military assistance","cn":"技术／经济／军事援助"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"帮助;协助","en":"If you give someone assistance, you help them do a job or task by doing part of the work for them.","ex":{"en":"Since 1976 he has been operating the shop with the assistance of volunteers","cn":"从1976年开始，他就在志愿者的帮助下经营这个店。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（以提供信息或意见的方式给予的）帮助，援助","en":"If you give someone assistance, you give them information or advice.","ex":{"en":"Any assistance you could give the police will be greatly appreciated","cn":"您提供的任何帮助警方都将万分感谢。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"资助；补助","en":"If someone gives a person or country assistance, they help them by giving them money.","ex":{"en":"...a viable programme of economic assistance","cn":"切实可行的经济援助方案"}},{"pos":"N-UNCOUNT 不可数名词","cn":"辅助;协助","en":"If something is done with the assistance of a particular thing, that thing is helpful or necessary for doing it.","ex":{"en":"The translations were carried out with the assistance of a medical dictionary.","cn":"这些翻译是借助一本医学词典完成的。"}},{"pos":"PHRASE 短语","cn":"有帮助;有用处","en":"Someone or something that is of assistance to you is helpful or useful to you.","ex":{"en":"He was of great assistance to me in researches for my books","cn":"在我为写书所作的研究中，他提供了很大的帮助。"}},{"pos":"PHRASE 短语","cn":"（采取行动）帮助，援助","en":"If you come to someone's assistance, you take action to help them.","ex":{"en":"They are appealing to the world community to come to Jordan's assistance","cn":"他们正在呼吁国际社会向约旦伸出援手。"}}]},"examples":[{"en":"She offered me practical assistance with my research.","cn":"她给我的研究提供了实实在在的援助。"},{"en":"Despite his cries, no one came to his assistance.","cn":"尽管他喊叫，却没有人来帮助他。"}]},"ashamed":{"media":{"uk":"media/uk/ashamed__gb_1.mp3","us":"media/us/ashamed__us_1.mp3"},"oxford":{"phon":"əˈʃeɪmd","pos":"adjective","senses":[{"en":"feeling shame or feeling embarrassed about somebody/something or because of something you have done","cn":"惭愧；羞愧；尴尬","ex":{"en":"She was deeply ashamed of her behaviour at the party.","cn":"她对自己在聚会上的行为深感羞愧。"}},{"en":"unwilling to do something because of shame or fear of feeling embarrassed","cn":"因惭愧而不情愿；因怕尴尬而勉强","ex":{"en":"I'm ashamed to say that I lied to her.","cn":"我真不好意思说我向她撒了谎。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"惭愧的；羞耻的；害臊的","en":"If someone is ashamed, they feel embarrassed or guilty because of something they do or they have done, or because of their appearance.","ex":{"en":"I felt incredibly ashamed of myself for getting so angry","cn":"我对自己发那么大的火而深感惭愧。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（为…）感到羞耻的，感到难为情的","en":"If you are ashamed of someone, you feel embarrassed to be connected with them, often because of their appearance or because you disapprove of something they have done.","ex":{"en":"I've never told this to anyone, but it's true, I was terribly ashamed of my mum.","cn":"这件事我从来没告诉过别人，但是我真的为我妈感到很害臊。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"羞于…的；因尴尬而不愿…的","en":"If someone is ashamed to do something, they do not want to do it because they feel embarrassed about it.","ex":{"en":"Women are often ashamed to admit they are being abused.","cn":"妇女对受到的侵犯常常羞于承认。"}}]},"examples":[{"en":"The football riots made me ashamed to be English.","cn":"足球骚乱事件使我身为英国人汗颜得无地自容。"},{"en":"You should be ashamed of treating your daughter like that.","cn":"你这样对待自己的女儿应该感到羞愧。"}]},"assertive":{"media":{"uk":"media/uk/assertive__gb_1.mp3","us":"media/us/assertive__us_1.mp3"},"oxford":{"phon":"əˈsɜːtɪv","pos":"adjective","senses":[{"en":"expressing opinions or desires strongly and with confidence, so that people take notice","cn":"坚定自信的；坚决主张的","ex":{"en":"You should try and be more assertive.","cn":"你应该努力坚定信心。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"观点明确的；坚决主张的","en":"Someone who is assertive states their needs and opinions clearly, so that people take notice.","ex":{"en":"Women have become more assertive in the past decade.","cn":"女性在过去十年中已变得更加自信。"}}]},"examples":[{"en":"You should try and be more assertive.","cn":"你应该努力坚定信心。"},{"en":"an assertiveness training course","cn":"建立自信心训练班"}]},"aspect":{"media":{"uk":"media/uk/aspect__gb_1.mp3","us":"media/us/aspect__us_1.mp3"},"oxford":{"phon":"ˈæspekt","pos":"noun","senses":[{"en":"a particular part or feature of a situation, an idea, a problem, etc.; a way in which it may be considered","cn":"方面；层面","g":"[countable]","ex":{"en":"The book aims to cover all aspects of city life.","cn":"这本书旨在涵盖城市生活的各个方面。"}},{"en":"the appearance of a place, a situation or a person","cn":"样子；外观；外表","g":"[singular, uncountable]","lab":"formal","ex":{"en":"Events began to take on a more sinister aspect.","cn":"事情开始呈现较为不祥的征兆。"}},{"en":"the direction in which a building, window, piece of land, etc. faces; the side of a building that faces a particular direction","cn":"朝向；方位","g":"[countable, usually singular]","lab":"formal","ex":{"en":"Our room had a western aspect.","cn":"我们的房间朝西。"}},{"en":"the form of a verb that shows, for example, whether the action happens once or repeatedly, is completed or still continuing","cn":"（动词的）体（如表示动作等发生一次或多次、已完成或正在进行）","g":"[uncountable, countable]","lab":"grammar"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"方面;形态;特性","en":"An aspect of something is one of the parts of its character or nature.","ex":{"en":"Climate and weather affect every aspect of our lives","cn":"气候和天气影响着我们生活的方方面面。"}},{"pos":"N-COUNT 可数名词","cn":"（建筑物或窗的）朝向，方向","en":"The aspect of a building or window is the direction in which it faces.","ex":{"en":"The house had a south-west aspect.","cn":"这幢房子面向西南。"}},{"pos":"N-SING 单数名词","cn":"（事物的）外观,样子,特征","en":"If something begins to have a new aspect, it begins to have a new appearance or quality.","ex":{"en":"Our journey had taken on a new aspect. The countryside was no longer familiar","cn":"我们所到之地呈现出一派新景象。乡村变得不再熟悉。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（语法中动词的）体","en":"In grammar, aspect is the way that a verb group shows whether an activity is continuing, is repeated, or is completed. For example, in 'They were laughing', the verb is in the progressive aspect and shows that the action was continuing."}]},"examples":[{"en":"This was one aspect of her character he hadn't seen before.","cn":"这是他过去没有了解到的她的性格的一个方面。"},{"en":"She felt she had looked at the problem from every aspect.","cn":"她觉得她已从各个角度去考虑了这个问题。"}]},"assortment":{"media":{"uk":"media/uk/assortment__gb_1.mp3","us":"media/us/assortment__us_1.mp3"},"oxford":{"phon":"əˈsɔːtmənt","pos":"noun","senses":[{"en":"a collection of different things or of different types of the same thing","cn":"各种各样","ex":{"en":"a wide assortment of gifts to choose from","cn":"各式各样可供挑选的礼品"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"各式各样;五颜六色;什锦","en":"An assortment is a group of similar things that are of different sizes or colours or have different qualities.","ex":{"en":"...an assortment of cheese.","cn":"干酪什锦"}}]},"examples":[{"en":"a wide assortment of gifts to choose from","cn":"各式各样可供挑选的礼品"},{"en":"He was dressed in an odd assortment of clothes.","cn":"他穿着奇装异服。"}]},"ascend":{"oxford":{"phon":"əˈsend","pos":"verb","senses":[{"en":"to rise; to go up; to climb up","cn":"上升；升高；登高","lab":"figurative","ex":{"en":"The path started to ascend more steeply.","cn":"小径开始陡峭而上。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"攀登；登上","en":"If you ascend a hill or staircase, you go up it.","ex":{"en":"Mrs Clayton had to hold Lizzie's hand as they ascended the steps","cn":"拾级而上的时候克莱顿夫人不得不抓着莉齐的手。"}},{"pos":"VERB 动词","cn":"（楼梯、路）上升，升高","en":"If a staircase or path ascends, it leads up to a higher position.","ex":{"en":"A number of staircases ascend from the cobbled streets onto the ramparts.","cn":"一段石阶从鹅卵石路上一直向上直通城墙。"}},{"pos":"VERB 动词","cn":"（通常指垂直地）上升","en":"If something ascends, it moves up, usually vertically or into the air.","ex":{"en":"Keep the drill steady while it ascends and descends","cn":"打钻和提钻时要保持钻头平稳。"}},{"pos":"VERB 动词","cn":"升迁；升职；(君主)登基,即位","en":"If someone ascends to an important position, they achieve it or are appointed to it. When someone ascends a throne, they become king, queen, or pope.","ex":{"en":"...the same year he ascended to power","cn":"同年，他上台掌权。"}},{"pos":"VERB 动词","cn":"（事业、社会地位）提高；晋升","en":"If you ascend in your career or in society, you gradually achieve success or a higher status.","ex":{"en":"Mobutu ascended through the ranks, eventually becoming commander of the army","cn":"蒙博托出身行伍，通过一级级晋升，最终成为了陆军司令。"}},{"pos":"VERB 动词","cn":"（在某些宗教中指灵魂）升天，进入天堂","en":"In some religions, when someone's soul goes to heaven, you can say that they ascend to heaven.","ex":{"en":"...the belief that the souls of the faithful and virtuous would ascend to heaven.","cn":"虔诚和善良的灵魂会升入天堂的信仰"}},{"pos":"VERB 动词","cn":"（境界）上升；升华","en":"If something or someone ascends to a higher level, they reach a state that is better than the one they were in before.","ex":{"en":"The story ascends from a gothic tragedy to a miraculous fairy-tale.","cn":"故事从一个哥特式悲剧升华为神奇的童话。"}}]},"media":{"uk":"media/uk/ascend__gb_1.mp3","us":"media/us/ascend__us_1.mp3"},"examples":[{"en":"The air became colder as we ascended.","cn":"随着我们往上攀登，空气就寒冷起来。"},{"en":"The results, ranked in ascending order (= from the lowest to the highest) are as follows","cn":"结果按由低到高的顺序排列如下："}]},"assemble":{"media":{"uk":"media/uk/assemble__gb_1.mp3","us":"media/us/assemble__us_1.mp3"},"oxford":{"phon":"əˈsembl","pos":"verb","senses":[{"en":"to come together as a group; to bring people or things together as a group","cn":"聚集；集合；收集","g":"[intransitive, transitive]","ex":{"en":"All the students were asked to assemble in the main hall.","cn":"全体学生接到通知到大礼堂集合。"}},{"en":"to fit together all the separate parts of something, for example a piece of furniture","cn":"装配；组装","g":"[transitive]","ex":{"en":"The shelves are easy to assemble.","cn":"搁架容易装配。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）集合;（使）聚集;（使）集会","en":"When people assemble or when someone assembles them, they come together in a group, usually for a particular purpose such as a meeting.","ex":{"en":"There wasn't even a convenient place for students to assemble between classes","cn":"在课间，学生们连一个方便凑在一起的地方都没有。"}},{"pos":"VERB 动词","cn":"集合;组装;装配","en":"To assemble something means to collect it together or to fit the different parts of it together.","ex":{"en":"Greenpeace managed to assemble enough boats to waylay the ship at sea","cn":"绿色和平组织设法聚集起足够数量的小船在海上拦截该船。"}}]},"examples":[{"en":"The manager has assembled a world-class team.","cn":"经理已聚集了一个世界一流的团队。"},{"en":"All the students were asked to assemble in the main hall.","cn":"全体学生获通知到大礼堂集合。"}]},"asian":{"media":{"uk":"media/uk/asian__gb_1.mp3","us":"media/us/asian__us_1.mp3"},"oxford":{"phon":"ˈeɪʒn","pos":"noun","senses":[{"en":"a person from Asia, or whose family originally came from Asia","cn":"亚洲人","lab":"British English","ex":{"en":"British Asians","cn":"英籍亚裔"}},{"en":"of or connected with Asia","cn":"亚洲的","ex":{"en":"Asian music","cn":"亚洲音乐"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"亚洲人的，亚洲的（英国人尤用此词指称印度、巴基斯坦和孟加拉，美国人尤用此词指称中国、朝鲜、韩国、泰国、日本和越南）","en":"Someone or something that is Asian comes from or is associated with Asia. British people use this term especially to refer to India, Pakistan, and Bangladesh. Americans use this term especially to refer to China, Korea, Thailand, Japan, or Vietnam.","ex":{"en":"...Asian music.","cn":"亚洲音乐"}}]},"examples":[{"en":"British Asians","cn":"英裔亚洲人"},{"en":"Asian music","cn":"亚洲音乐"}]},"aspiration":{"media":{"uk":"media/uk/aspiration__gb_1.mp3","us":"media/us/aspiration__us_1.mp3"},"oxford":{"phon":"ˌæspəˈreɪʃn","pos":"noun","senses":[{"en":"a strong desire to have or do something","cn":"渴望；抱负；志向","g":"[countable, usually plural, uncountable]","ex":{"en":"I didn't realize you had political aspirations.","cn":"我没有意识到你有政治上的抱负。"}},{"en":"the action of pronouncing a word with a breath that can be heard, as in the /h/ sound in house in English","cn":"送气；发送气音","g":"[uncountable]","lab":"phonetics"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"抱负；志向；渴望","en":"Some-one's aspirations are their desire to achieve things.","ex":{"en":"...the needs and aspirations of our pupils","cn":"我们的学生的需要和志向"}}]},"examples":[{"en":"What changes are needed to meet women's aspirations for employment?","cn":"需要什么样的改革才能满足女性对就业的渴望呢？"},{"en":"I didn't realize you had political aspirations.","cn":"我没有意识到你有政治上的抱负。"}]},"assign":{"oxford":{"phon":"əˈsaɪn","pos":"verb","senses":[{"en":"to give somebody something that they can use, or some work or responsibility","cn":"分配（某物）；分派，布置（工作、任务等）","ex":{"en":"The teacher assigned a different task to each of the children.","cn":"老师给每个孩子都布置了不同的作业。"}},{"en":"to provide a person for a particular task or position","cn":"指定；指派","ex":{"en":"They've assigned their best man to the job.","cn":"他们指派了最优秀的人承担这项工作。"}},{"en":"to send a person to work under the authority of somebody or in a particular group","cn":"委派；派遣","g":"[usually passive]","ex":{"en":"I was assigned to B platoon.","cn":"我被派到 B 排工作。"}},{"en":"to say that something has a particular value or function, or happens at a particular time or place","cn":"确定（价值、功能、时间、地点）","ex":{"en":"Assign a different colour to each different type of information.","cn":"给每类信息分别确定一种颜色。"}},{"en":"to say that your property or rights now belong to somebody else","cn":"转让，让与（财产、权利）","lab":"law","ex":{"en":"The agreement assigns copyright to the publisher.","cn":"协议规定将版权转让给出版商。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"分派（工作）；布置（作业）","en":"If you assign a piece of work to someone, you give them the work to do.","ex":{"en":"When I taught, I would assign a topic to children which they would write about","cn":"我教课时会给孩子们布置一个题目，让他们就这个题目写点东西。"}},{"pos":"VERB 动词","cn":"分配;配给","en":"If you assign something to someone, you say that it is for their use.","ex":{"en":"The selling broker is then required to assign a portion of the commission to the buyer broker","cn":"卖方经纪人须随后将部分佣金分给买方经纪人。"}},{"pos":"VERB 动词","cn":"委派;派往;指派","en":"If someone is assigned to a particular place, group, or person, they are sent there, usually in order to work at that place or for that person.","ex":{"en":"I was assigned to Troop A of the 10th Cavalry","cn":"我被派往第10骑兵队的A连。"}},{"pos":"VERB 动词","cn":"赋予，给予（功能或价值）","en":"If you assign a particular function or value to someone or something, you say they have it.","ex":{"en":"Under Mr. Harel's system, each business must assign a value to each job","cn":"根据哈雷尔先生的体系，每个企业必须赋予每份工作一定的价值。"}}]},"media":{"uk":"media/uk/assign__gb_1.mp3","us":"media/us/assign__us_1.mp3"},"examples":[{"en":"The teacher assigned a different task to each of the children.","cn":"老师给每个孩子都布置了不同的作业。"},{"en":"The teacher assigned each of the children a different task.","cn":"老师给每个孩子都布置了不同的作业。"}]},"assured":{"oxford":{"phon":"əˈʃʊəd","pos":"adjective","senses":[{"en":"confident in yourself and your abilities","cn":"自信的；有把握的","ex":{"en":"He spoke in a calm, assured voice.","cn":"他冷静自信地说。"}},{"en":"certain to happen","cn":"必将发生的；确定的","ex":{"en":"Success seemed assured.","cn":"看来已必胜无疑。"}},{"en":"certain to get something","cn":"肯定得到","ex":{"en":"You are assured of a warm welcome at this hotel.","cn":"你在这家旅馆肯定会受到热情欢迎。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自信的；放松的；有把握的","en":"Someone who is assured is very confident and relaxed.","ex":{"en":"He was infinitely more assured than in his more recent parliamentary appearances.","cn":"比起最近几次在国会中的露面，他表现得自信多了。"}},{"pos":"ADJ 形容词","cn":"确定的；毫无疑问的","en":"If something is assured, it is certain to happen.","ex":{"en":"Our victory is assured; nothing can stop us","cn":"我们必胜，我们锐不可当。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"确定的;信心十足的;志在必得的","en":"If you are assured of something, you are certain to get it or achieve it.","ex":{"en":"Laura Davies is assured of a place in Europe's team","cn":"劳拉·戴维斯确信能在欧洲队中占据一席之地。"}},{"pos":"PHRASE 短语","cn":"可以放心；可以安心","en":"If you say that someone can rest assured that something is the case, you mean that it is definitely the case, so they do not need to worry about it.","ex":{"en":"Their parents can rest assured that their children's safety will be of paramount importance","cn":"家长尽可放心，孩子们的安全将成为重中之重。"}},{"pos":"PHRASE 短语","cn":"必定，一定会（做某事）","en":"You use rest assured when you want to emphasize your determination to do something.","ex":{"en":"I will be seeing Mr and Mrs. Johnson. And rest assured I will tell them of your rudeness","cn":"我将去见约翰逊夫妇。等着瞧吧，我一定会把你的无礼告诉他们。"}}]},"media":{"uk":"media/uk/assured__gb_1.mp3","us":"media/us/assured__us_1.mp3"},"examples":[{"en":"You are assured of a warm welcome at this hotel.","cn":"你在这家旅馆肯定会受到热情欢迎。"},{"en":"He spoke in a calm, assured voice.","cn":"他冷静自信地说。"}],"base":"assure"},"aspiring":{"media":{"uk":"media/uk/aspiring__gb_1.mp3","us":"media/us/aspiring__us_1.mp3"},"oxford":{"phon":"əˈspaɪərɪŋ","pos":"adjective","senses":[{"en":"wanting to start the career or activity that is mentioned","cn":"有抱负的；有雄心壮志的","ex":{"en":"Aspiring musicians need hours of practice every day.","cn":"想当音乐家就要每天练好几个小时。"}},{"en":"wanting to be successful in life","cn":"有抱负的；有志向的","ex":{"en":"He came from an aspiring working-class background.","cn":"他出身于有抱负的工人阶级家庭。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"有抱负的；有志向的","en":"If you use aspiring to describe someone who is starting a particular career, you mean that they are trying to become successful in it.","ex":{"en":"Many aspiring young artists are advised to learn by copying the masters.","cn":"许多胸怀抱负的年轻画家被建议通过临摹大师的作品来学习绘画。"}}]},"examples":[{"en":"Aspiring musicians need hours of practice every day.","cn":"想当音乐家就要每天练许多小时。"},{"en":"He came from an aspiring working-class background.","cn":"他出身于有抱负的工人阶级家庭。"}],"base":"aspire"},"assessment":{"media":{"uk":"media/uk/assessment__gb_1.mp3","us":"media/us/assessment__us_1.mp3"},"oxford":{"phon":"əˈsesmənt","pos":"noun","senses":[{"en":"an opinion or a judgement about somebody/something that has been thought about very carefully","cn":"看法；评价","g":"[countable]","ex":{"en":"a detailed assessment of the risks involved","cn":"对涉及的风险所作的详细判断"}},{"en":"the act of judging or forming an opinion about somebody/something","cn":"评定；核定；判定","g":"[uncountable]","ex":{"en":"Objective assessment of the severity of the problem was difficult.","cn":"难以客观判定该问题的严重性。"}},{"en":"the process of testing students and making a judgement about their knowledge, ability or progress","cn":"（对学生的）评价，考核","g":"[uncountable]","ex":{"en":"written exams and other forms of assessment","cn":"笔试及其他形式的考核"}},{"en":"an amount that has been calculated and that must be paid","cn":"核定的付款额","g":"[countable]","ex":{"en":"a tax assessment","cn":"税款核定额"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"评估;评定;鉴定","en":"An assessment is a consideration of someone or something and a judgment about them.","ex":{"en":"There is little assessment of the damage to the natural environment","cn":"几乎未对自然环境破坏程度作出评估。"}},{"pos":"N-VAR 可变名词","cn":"（价值的）评估，评定;估价","en":"An assessment of the amount of money that something is worth or that should be paid is a calculation or estimate of the amount.","ex":{"en":"Price Waterhouse have traced the losses to lenders' inflated assessments of mortgaged property.","cn":"普华永道会计师事务所已经查明损失源于贷方对按揭财产估值过高。"}}]},"examples":[{"en":"Objective assessment of the severity of the problem was difficult.","cn":"难以客观判定该问题的严重性。"},{"en":"a detailed assessment of the risks involved","cn":"对涉及的风险所作的详细判断"}]},"assistants":{"lemma":"assistant"},"assigned":{"lemma":"assign"},"associate":{"media":{"uk":"media/uk/associate__gb_1.mp3","us":"media/us/associate__us_1.mp3"},"oxford":{"phon":"əˈsəʊsieɪt","pos":"verb","senses":[{"en":"to make a connection between people or things in your mind","cn":"联想；联系","g":"[transitive]","ex":{"en":"I always associate the smell of baking with my childhood.","cn":"一闻到烘烤食物的味道，我就想起了童年。"}},{"en":"to spend time with somebody, especially a person or people that somebody else does not approve of","cn":"交往；（尤指）混在一起","g":"[intransitive]","ex":{"en":"I don't like you associating with those people.","cn":"我不喜欢你和那些人混在一起。"}},{"en":"to show that you support or agree with something","cn":"表明支持；表示同意","g":"[transitive]","lab":"formal","ex":{"en":"I associate myself with the prime minister's remarks (= I agree with them).","cn":"我赞同首相所言。"}},{"en":"of a lower rank; having fewer rights in a particular profession or organization","cn":"非正式的；准的；副的","ex":{"en":"associate membership of the European Union","cn":"欧洲联盟的非正式会员身份"},"pos":"adjective"},{"en":"joined to or connected with a profession or an organization","cn":"联合的；有关联的","ex":{"en":"an associate company in Japan","cn":"在日本的一家联营公司"},"pos":"adjective"},{"en":"a person that you work with, do business with or spend a lot of time with","cn":"同事；伙伴","ex":{"en":"business associates","cn":"业务伙伴"},"pos":"noun"},{"en":"an associate member","cn":"准会员","pos":"noun"},{"en":"a person who has an Associate’s degree (= one that is given after completing two years of study at a junior college)","cn":"准学士（获得两年制高校学位）","lab":"US English","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"联系;联想","en":"If you associate someone or something with another thing, the two are connected in your mind.","ex":{"en":"Through science we've got the idea of associating progress with the future","cn":"通过科学我们知道了应该把进步和未来联系起来。"}},{"pos":"VERB 动词","cn":"使与（某个组织、事业或观点）有关系;公开支持","en":"If you are associated with a particular organization, cause, or point of view, or if you associate yourself with it, you support it publicly.","ex":{"en":"I haven't been associated with the project over the last year","cn":"我去年一直没有参与那个项目。"}},{"pos":"VERB 动词","cn":"与…为伍;与…交往;与…厮混","en":"If you say that someone is associating with another person or group of people, you mean they are spending a lot of time in the company of people you do not approve of.","ex":{"en":"What would they think if they knew that they were associating with a murderer?","cn":"如果他们知道自己正在与一个杀人犯为伍会怎么想?"}},{"pos":"N-COUNT 可数名词","cn":"（尤指）同事;合作人;伙伴","en":"Your associates are the people you are closely connected with, especially at work.","ex":{"en":"...the restaurant owner's business associates.","cn":"餐馆老板的商业伙伴"}},{"pos":"ADJ 形容词","cn":"（用于等级或头衔前，表示稍有不同或略低）副的，准的","en":"Associate is used before a rank or title to indicate a slightly different or lower rank or title.","ex":{"en":"Mr Lin is associate director of the Institute","cn":"林先生是研究所的副所长。"}}]},"examples":[{"en":"He is closely associated in the public mind with horror movies.","cn":"在公众的心目中，他总是和恐怖电影紧密联系在一起。"},{"en":"I always associate the smell of baking with my childhood.","cn":"一闻到烘烤食物的味道，我就想起了童年。"}]},"assumed":{"media":{"uk":"media/uk/assumed__gb_1.mp3","us":"media/us/assumed__us_1.mp3"},"oxford":{"phon":"əˈsjuːmd","pos":"adjective","senses":[{"en":"that you suppose to be true or to exist","cn":"假定的；假设的","ex":{"en":"the assumed differences between the two states","cn":"两种状况的假定区别"}}]},"examples":[{"en":"the assumed differences between the two states","cn":"两种状况的假定区别"}],"base":"assume"},"astonishing":{"oxford":{"phon":"əˈstɒnɪʃɪŋ","pos":"adjective","senses":[{"en":"very surprising; difficult to believe","cn":"令人十分惊讶的；使人大为惊奇的；难以置信的","ex":{"en":"She ran 100m in an astonishing 10.6 seconds.","cn":"她以 10.6 秒的惊人速度跑完了 100 米。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人惊讶的；非常惊人的","en":"Something that is astonishing is very surprising.","ex":{"en":"It's astonishing, he's learned Latin in three hours!","cn":"他花了3个小时就学会了拉丁文，真让人吃惊！"}}]},"media":{"uk":"media/uk/astonishing__gb_1.mp3","us":"media/us/astonishing__us_1.mp3"},"examples":[{"en":"She ran 100m in an astonishing 10.6 seconds.","cn":"她以 10.6 秒的惊人速度跑完了 100 米。"},{"en":"Astonishingly, a crowd of several thousands turned out to hear him.","cn":"令人十分惊异的是有几千人来听他讲话。"}]},"associating":{"lemma":"associate"},"assumptions":{"lemma":"assumption"},"asked":{"lemma":"ask"},"assets":{"lemma":"asset"},"asserts":{"lemma":"assert"},"aspects":{"lemma":"aspect"},"assists":{"lemma":"assist"},"asking":{"lemma":"ask"},"asymmetrical":{"oxford":{"phon":"ˌeɪsɪˈmetrɪk","pos":"adj.","senses":[{"en":"having two sides or parts that are not the same in size or shape","cn":"不对称的"},{"en":"( technical","cn":"术语 ) not equal, for example in the way each side or part behaves 不对等的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不对称的","en":"Something that is asymmetrical has two sides or halves that are different in shape, size, or style.","ex":{"en":"...asymmetrical shapes.","cn":"不对称形状"}}]},"media":{"uk":"media/ldoce/hwd/bre/d/a432new3.mp3","us":"media/ldoce/hwd/ame/e/laadasymmetrical.mp3"},"examples":[{"en":"asymmetrical patterns","cn":"不对称图案"}]},"asians":{"lemma":"asian"},"associations":{"lemma":"association"},"asserted":{"lemma":"assert"},"assisted":{"lemma":"assist"},"assassin":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"暗杀者；刺客","en":"An assassin is a person who assassinates someone.","ex":{"en":"He saw the shooting and memorised the number of the assassin's car.","cn":"他目睹了枪击过程并记住了刺客的车牌号码。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has deliberately killed another person","cn":""},{"en":"someone who deliberately kills someone else - used especially in newspapers","cn":""},{"en":"someone who kills a famous or important person, sometimes because someone else has paid them to do it","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An assassin is someone who murders an important political or religious leader. Brutus is one of the most infamous assassins in history. He murdered Julius Caesar, who ruled Rome in the first century B.C."}]},"collocations":{"phrases":["ADJ. attempted, would-be | hired, professional He was killed by a hired assassin. | trained"]},"media":{"uk":"media/ldoce/hwd/bre/b/assassin0205.mp3","us":"media/ldoce/hwd/ame/c/assassin.mp3"},"examples":[{"en":"Kennedy’s assassin is assumed to have been Lee Harvey Oswald.","cn":"暗杀肯尼迪的人据说是李·哈维·奥斯瓦尔德。"}],"oxford":{"phon":"əˈsæsɪn","pos":"noun","senses":[{"en":"a person who murders somebody important or famous, for money or for political reasons","cn":"（为金钱或政治目的的）暗杀者，行刺者","ex":{"en":"a hired/professional assassin","cn":"受雇/职业刺客"}}]}},"assert":{"collins":{"senses":[{"pos":"VERB 动词","cn":"坚称;断言;坚决表明","en":"If someone asserts a fact or belief, they state it firmly.","ex":{"en":"Mr. Helm plans to assert that the bill violates the First Amendment","cn":"赫尔姆先生打算声明该法案违反了宪法第一修正案。"}},{"pos":"VERB 动词","cn":"维护，坚持（权威）","en":"If you assert your authority, you make it clear by your behaviour that you have authority.","ex":{"en":"After the war, the army made an attempt to assert its authority in the south of the country","cn":"战后，军队试图在该国的南部地区维护其统治地位。"}},{"pos":"VERB 动词","cn":"坚持（主张）；要求（权利）","en":"If you assert your right or claim to something, you insist that you have the right to it.","ex":{"en":"The republics began asserting their right to govern themselves.","cn":"各加盟共和国开始要求获得自治权。"}},{"pos":"VERB 动词","cn":"坚持（自己）的主张;表现坚定","en":"If you assert yourself, you speak and act in a forceful way, so that people take notice of you.","ex":{"en":"He's speaking up and asserting himself confidently.","cn":"他明确表态，信心十足地阐述自己的观点。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say that something is true, even though it has not been proved","cn":""},{"en":"to claim that someone did something wrong or illegal, although you do not give any proof","cn":""},{"en":"to repeatedly say that something is true, especially when other people do not believe you","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Asserting is all about standing up for what you believe. You might assert an opinion, your innocence, or even your authority over someone else."}]},"collocations":{"phrases":["ADV. boldly, confidently, emphatically, forcefully, strongly The report asserts confidently that the industry will grow. | directly, explici","ADV. successfully They successfully asserted their right to protect their homes.","VERB + ASSERT need to | be determined to, wish to She wished to assert her independence from her parents. | seek to, try to | be able to, ma"]},"media":{"uk":"media/ldoce/hwd/bre/5/assert0205.mp3","us":"media/ldoce/hwd/ame/e/assert.mp3"},"examples":[{"en":"It is commonly asserted that older people prefer to receive care from family members.","cn":"人们普遍确认，老年人更愿意由家人照顾。"},{"en":"I was determined to assert my authority from the beginning.","cn":"我决心一开始就维护我的权威。"}],"oxford":{"phon":"əˈsɜːt","pos":"verb","senses":[{"en":"to state clearly and definitely that something is true","cn":"明确肯定；断言","ex":{"en":"She continued to assert that she was innocent.","cn":"她仍然坚称自己无辜。"}},{"en":"to behave in a confident and determined way so that other people pay attention to your opinions","cn":"坚持自己的主张；表现坚定","ex":{"en":"You’re too timid—you must try to assert yourself more.","cn":"你太畏缩了--要尽量增强自信心。"}},{"en":"to make other people recognize your right or authority to do something, by behaving in a determined and confident way","cn":"维护自己的权利（或权威）","ex":{"en":"to assert your independence/rights","cn":"维护你的独立／权利"}},{"en":"to start to have an effect","cn":"生效；起作用","ex":{"en":"Good sense asserted itself.","cn":"明智服人。"}}]}},"assist":{"collins":{"senses":[{"pos":"VERB 动词","cn":"帮助，协助(完成工作)","en":"If you assist someone, you help them to do a job or task by doing part of the work for them.","ex":{"en":"Julia was assisting him to prepare his speech","cn":"朱莉娅正在帮他准备讲演稿。"}},{"pos":"VERB 动词","cn":"（提供信息、意见或金钱）帮助，援助","en":"If you assist someone, you give them information, advice, or money.","ex":{"en":"The public is urgently requested to assist police in tracing this man","cn":"紧急要求公众帮助警方追踪此人。"}},{"pos":"VERB 动词","cn":"有助于;促进","en":"If something assists in doing a task, it makes the task easier to do.","ex":{"en":"...a chemical that assists in the manufacture of proteins","cn":"有助于生成蛋白质的一种化学物质"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make it easier for someone to do something, by doing something for them or giving them something they need","cn":""},{"en":"to help someone","cn":""},{"en":"to help someone to do something – used especially when saying that something helps your body to do something","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"You run up the field, pass the ball to the forward and she scores! It’s your third assist of the game. On and off the soccer field, to assist is to help or contribute."}]},"collocations":{"phrases":["ADV. greatly, materially We have been greatly assisted by individuals and organizations. | actively","VERB + ASSIST be designed to measures designed to assist people with disabilities","PREP. in He had to assist her in opening the gates. | with She offered to assist with the marketing of the product."]},"media":{"uk":"media/ldoce/hwd/bre/7/assist_n0205.mp3","us":"media/ldoce/hwd/ame/d/assist.mp3"},"examples":[{"en":"The play was directed by Mike Johnson, assisted by Sharon Gale.","cn":"该剧由迈克 · 约翰逊导演，沙伦 · 盖尔为助理导演。"},{"en":"We are looking for people who would be willing to assist in the group's work.","cn":"我们正寻找愿意协助该团体工作的人。"}],"oxford":{"phon":"əˈsɪst","pos":"verb","senses":[{"en":"to help somebody to do something","cn":"帮助；协助；援助","g":"[intransitive, transitive]","ex":{"en":"Anyone willing to assist can contact this number.","cn":"凡愿协助者可拨此号码联系。"}},{"en":"to help something to happen more easily","cn":"促进","g":"[transitive]","ex":{"en":"activities that will assist the decision-making process","cn":"促进决策进程的活动"}},{"en":"an action in ice hockey, football (soccer), etc. in which a player passes the ball in a way that helps another player on the same team to score a goal","cn":"（冰球、足球等运动中的）助攻","ex":{"en":"He had/made ten assists.","cn":"他有十次助攻。"},"pos":"noun"},{"en":"an action in baseball in which a player throws the ball to another member of the team who gets an opponent out either by stepping onto the base before the runner reaches it, or by touching the runner with the ball before they reach the base","cn":"（棒球运动中的）助杀","pos":"noun"}]}},"assurance":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"保证；确保","en":"If you give someone an assurance that something is true or will happen, you say that it is definitely true or will definitely happen, in order to make them feel less worried.","ex":{"en":"He would like an assurance that other forces will not move into the territory that his forces vacate","cn":"他想确保其他势力不会在他的军队撤离后进入这个地区。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"信心；把握","en":"If you do something with assurance, you do it with a feeling of confidence and certainty.","ex":{"en":"Masur led the orchestra with assurance","cn":"马苏尔神定气若地指挥乐团。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（人寿）保险","en":"Assurance is insurance that provides cover in the event of death.","ex":{"en":"...endowment assurance.","cn":"养老保险"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the feeling that you have the ability to do things well, and to not make mistakes or be nervous in new situations","cn":""},{"en":"a strong belief that you can do things well and that other people will like you, which means you behave confidently in most situations","cn":""},{"en":"the level of confidence, satisfaction, and hope that people feel, especially a group of people who work together","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"An assurance is a vote of confidence. If you give your friend an assurance that you'll be there, you better show up."}]},"collocations":{"phrases":["ADJ. absolute, categorical, clear, firm, full | further, repeated | formal, official, personal, verbal, written He gave me his personal assu","VERB + ASSURANCE have We now have a firm assurance of support from the government. | give sb, offer sb, provide | gain, get, obtain, receive","PREP. ~ about an assurance about the safety of this equipment | ~ by/from assurances from the head teacher","PHRASES despite/in spite of assurances Despite assurances from the government, the chemicals are known to be dangerous. 2 feeling of calm an","ADJ. calm, quiet She spoke with calm assurance.","VERB + ASSURANCE have | show Even at a very young age she showed a great deal of assurance."]},"media":{"uk":"media/ldoce/hwd/bre/f/assurance0205.mp3","us":"media/ldoce/hwd/ame/0/assurance.mp3"},"examples":[{"en":"Unemployment seems to be rising, despite repeated assurances to the contrary.","cn":"尽管反复担保减少失业，失业率看来却在上升。"},{"en":"They called for assurances that the government is committed to its education policy.","cn":"他们要求政府保证切实执行其教育方针。"}],"oxford":{"phon":"əˈʃʊərəns","pos":"noun","senses":[{"en":"a statement that something will certainly be true or will certainly happen, particularly when there has been doubt about it","cn":"保证；担保","g":"[countable]","ex":{"en":"They called for assurances that the government is committed to its education policy.","cn":"他们要求政府保证切实执行其教育方针。"}},{"en":"belief in your own abilities or strengths","cn":"自信","g":"[uncountable]","ex":{"en":"There was an air of easy assurance about him.","cn":"他表现得从容淡定。"}},{"en":"a type of insurance in which money is paid out when somebody dies or after an agreed period of time","cn":"人寿保险","g":"[uncountable]","lab":"British English","ex":{"en":"a life assurance company","cn":"人寿保险公司"}}]}},"ash":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"灰；灰烬","en":"Ash is the grey or black powdery substance that is left after something is burnt. You can also refer to this substance as ashes .","ex":{"en":"A cloud of volcanic ash is spreading across wide areas of the Philippines","cn":"火山灰云层正在菲律宾大范围扩散。"}},{"pos":"N-PLURAL 复数名词","cn":"骨灰","en":"A dead person's ashes are their remains after their body has been cremated."},{"pos":"N-VAR 可变名词","cn":"白蜡树;","en":"An ash is a tree that has smooth grey bark and loses its leaves in winter.","ex":{"en":"...a high forest of oak and ash.","cn":"生长着橡树和白蜡树的高山林"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the soft grey powder that remains after something has been burned","cn":"灰﹐灰烬"},{"en":"the ash that remains when a dead person’s body is burned","cn":"骨灰"},{"en":"a situation in which something is completely destroyed","cn":"废墟﹐灰烬〔指完全被毁的局面〕"}]},"collocations":{"phrases":["ADJ. glowing, hot, red-hot, smouldering the glowing ashes of the dying fire | cold, dead The fire had died to cold ashes. | fine Fine ash co","QUANT. cloud A cloud of ash rose from the volcano.","VERB + ASH flick, tap (used about cigarette ash) He flicked ash into the ashtray. | reduce sth to, turn to ~es a village reduced to ashes by","ASH + VERB fall Ash from the volcano fell over a wide area.","PHRASES rise from the ashes (figurative) The party had risen, like a phoenix, from the ashes of electoral disaster. 2 ashes: remains of a de","VERB + ASH scatter His ashes were scattered on his beloved farm."]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdeash.mp3","us":"media/ldoce/hwd/ame/f/ash1.mp3","img":["media/thumb/ash.jpg"]},"examples":[{"en":"( figurative ) The party had risen, like a phoenix, from the ashes of electoral disaster.","cn":"该党像长生鸟一样，从选举惨败的灰烬中重新崛起。"},{"en":"The town was reduced to ashes in the fighting.","cn":"在战斗中这座城镇已化为灰烬。"}],"oxford":{"phon":"æʃ","pos":"noun","senses":[{"en":"the grey or black powder that is left after something, especially tobacco, wood or coal, has burnt","cn":"灰；灰烬","g":"[uncountable]","ex":{"en":"cigarette ash","cn":"香烟灰"}},{"en":"what is left after something has been destroyed by burning","cn":"灰烬；废墟","g":"[plural]","lab":"figurative","ex":{"en":"The town was reduced to ashes in the fighting.","cn":"这座城镇在战斗中化为灰烬。"}},{"en":"the powder that is left after a dead person’s body has been cremated (= burned)","cn":"骨灰","g":"[plural]","ex":{"en":"She wanted her ashes to be scattered at sea.","cn":"她希望自己的骨灰撒向大海。"}},{"en":"a forest tree with grey bark","cn":"梣；白蜡树","g":"[countable, uncountable]"},{"en":"the hard pale wood of the ash tree","cn":"梣木","g":"[uncountable]"},{"en":"the letter æ, used in Old English, and as a phonetic symbol to represent the vowel sound in cat","cn":"æ（古英语的一个字母，也为音标，表示如 cat 一词中的元音）","lab":"specialist"},{"en":"Action on Smoking and Health (an organization in the UK that tries to make people stop smoking by showing how dangerous it is)","cn":"吸烟与健康行动（英国倡导戒烟的组织）","pos":"abbreviation"}]}},"assure":{"collins":{"senses":[{"pos":"VERB 动词","cn":"向…保证；使…确信；使…放心","en":"If you assure someone that something is true or will happen, you tell them that it is definitely true or will definitely happen, often in order to make them less worried.","ex":{"en":"He hastened to assure me that there was nothing traumatic to report","cn":"他忙不迭地向我保证，并没有什么悲惨的事要诉说。"}},{"pos":"VERB 动词","cn":"保证，确保（得到）","en":"To assure someone of something means to make certain that they will get it.","ex":{"en":"Last night's resounding victory over Birmingham City has virtually assured them of promotion","cn":"昨晚大胜伯明翰城队实际上已确保他们能够晋级。"}},{"pos":"PHRASE 短语","cn":"我可以向你保证；相信我","en":"You use phrases such as I can assure you or let me assure you to emphasize the truth of what you are saying.","ex":{"en":"I can assure you that the animals are well cared for","cn":"我可以向你保证动物们得到了精心照顾。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to tell someone that you will definitely do something, or that something will happen","cn":""},{"en":"to make a very serious and sincere promise, for example in a law court","cn":""},{"en":"to promise sincerely that you will do something or that something is true – often used when you are trying to persuade someone that they can trust you","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"If you assure your boss that you’ll finish your project by Tuesday, you are make a promise or commitment to have it done by Tuesday."}]},"collocations":{"phrases":["VERB + ASSURE can | hasten to He hastened to assure us that the press would not be informed.","PREP. of We can assure you of our full support.","PHRASES let me assure you"]},"media":{"uk":"media/ldoce/hwd/bre/1/assure0205.mp3","us":"media/ldoce/hwd/ame/0/assure.mp3"},"examples":[{"en":"You think I did it deliberately, but I assure you (that) I did not.","cn":"你认为这是我故意干的，不过我向你保证不是的。"},{"en":"She's perfectly safe, I can assure you.","cn":"我可以向你保证，她绝对安全。"}],"oxford":{"phon":"əˈʃʊə(r)","pos":"verb","senses":[{"en":"to tell somebody that something is definitely true or is definitely going to happen, especially when they have doubts about it","cn":"使确信；向…保证","ex":{"en":"You think I did it deliberately, but I assure you (that) I did not.","cn":"你认为这是我故意干的，不过我向你保证不是的。"}},{"en":"to make yourself certain about something","cn":"弄清；查明","lab":"formal","ex":{"en":"He assured himself of her safety.","cn":"他确定她是安全的。"}},{"en":"to make something certain to happen","cn":"使必然发生；确保","ex":{"en":"Victory would assure a place in the finals.","cn":"胜利将确保能参加决赛。"}},{"en":"to insure something, especially against somebody’s death","cn":"保险（尤指人寿险）","lab":"British English","ex":{"en":"What is the sum assured?","cn":"人寿保险额是多少？"}}]}},"assimilate":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）同化；（使）融入","en":"When people such as immigrants assimilate into a community or when that community assimilates them, they become an accepted part of it.","ex":{"en":"There is every sign that new Asian-Americans are just as willing to assimilate","cn":"种种迹象表明新一代亚裔美国人也愿意入乡随俗。"}},{"pos":"VERB 动词","cn":"吸收；接受；学习","en":"If you assimilate new ideas, techniques, or information, you learn them or adopt them.","ex":{"en":"I was speechless, still trying to assimilate the enormity of what he'd told me.","cn":"我无话可说，一时还无法接受他对我所说之事的严重性。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to understand new information, especially when there is a large amount of it or when it is difficult to understand, by thinking about it carefully for a fairly long time","cn":""},{"en":"to understand and remember new facts or information","cn":""},{"en":"to understand a large amount of new information","cn":""}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"If you are trying to fit in, you are trying to assimilate ."}]},"collocations":{"phrases":["ADV. easily, quickly, readily Children assimilate new information very quickly. 2 become/make sb part of sth","ADV. fully Many new immigrants have not yet assimilated fully into the new culture.","PREP. into"]},"media":{"uk":"media/ldoce/hwd/bre/b/assimilate0205.mp3","us":"media/ldoce/hwd/ame/d/assimilate.mp3"},"examples":[{"en":"The committee will need time to assimilate this report.","cn":"委员会需要时间来吃透这个报告。"},{"en":"New arrivals find it hard to assimilate.","cn":"新来者感到难以融入当地社会。"}],"oxford":{"phon":"əˈsɪməleɪt","pos":"verb","senses":[{"en":"to fully understand an idea or some information so that you are able to use it yourself","cn":"透彻理解；消化；吸收","g":"[transitive]","ex":{"en":"The committee will need time to assimilate this report.","cn":"委员会需要时间来吃透这个报告。"}},{"en":"to become, or cause somebody to become, a part of a country or community rather than remaining in a separate group","cn":"（使）同化，融入","g":"[intransitive, transitive]","ex":{"en":"New arrivals feel the pressure to assimilate.","cn":"新来者感受到了融入社会的压力。"}},{"en":"to make an idea, a person’s attitude, etc. fit into something or be acceptable","cn":"使吸收，使接受（想法、态度等）","g":"[transitive, often passive]","ex":{"en":"These changes were gradually assimilated into everyday life.","cn":"这些改变逐渐渗进了日常生活。"}}]}},"assignment":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（布置的）作业;（分配的）任务","en":"An assignment is a task or piece of work that you are given to do, especially as part of your job or studies.","ex":{"en":"The assessment for the course involves written assignments and practical tests.","cn":"这门功课的考核包括书面作业和实际操作考试。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（任务、工作的）分配，指派","en":"You can refer to someone being given a particular task or job as their assignment to the task or job.","ex":{"en":"An Australian division scheduled for assignment to Greece was ordered to remain in Egypt.","cn":"原定去希腊执行任务的一支澳大利亚小分队接到命令后继续留在埃及。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a specific piece of work that you have to do, often one that you are not paid for","cn":""},{"en":"a piece of work that you have to do - use this especially about a difficult or unpleasant job, or about a specific part of your work","cn":""},{"en":"a job that you have to do, either for your work or for yourself, especially things that you have to leave your office or house to do","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Whether you’re an international spy with a new mission or a high school student with math homework — when you get an assignment , you’d better do it! An assignment is a task that someone in authority has asked you to do."}]},"collocations":{"phrases":["ADJ. special | important | dangerous, difficult, tough | business, work | modelling, photographic","VERB + ASSIGNMENT accept, take on Why did you take on this assignment if you're so busy? | carry out | refuse If you refuse this assignment ","PREP. on ~ The photographer is on assignment in China at the moment. 2 piece of school/college work","ADJ. practical, reading, written","VERB + ASSIGNMENT give, hand out, set The teacher set an assignment on pollution. | do | complete, finish | hand in The students handed in t","PREP. ~ on an assignment on Roman history"]},"media":{"uk":"media/ldoce/hwd/bre/f/assignment0205.mp3","us":"media/ldoce/hwd/ame/1/assignment.mp3"},"examples":[{"en":"She is in Greece on an assignment for one of the Sunday newspapers.","cn":"她在希腊为一家星期日报执行一项任务。"},{"en":"You will need to complete three written assignments per semester.","cn":"你每学期要完成三个书面作业。"}],"oxford":{"phon":"əˈsaɪnmənt","pos":"noun","senses":[{"en":"a task or piece of work that somebody is given to do, usually as part of their job or studies","cn":"（分派的）工作，任务","g":"[countable]","ex":{"en":"Students are required to complete all homework assignments.","cn":"要求学生完成所有家庭作业。"}},{"en":"the act of giving something to somebody; the act of giving somebody a particular task","cn":"（工作等的）分派，布置","g":"[uncountable]","ex":{"en":"his assignment to other duties in the same company","cn":"他在同一公司内担任的其他职务"}}]}},"assent":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"同意；准许；批准","en":"If someone gives their assent to something that has been suggested, they formally agree to it.","ex":{"en":"He gave his assent to the proposed legislation","cn":"他批准了提请审议的法案。"}},{"pos":"VERB 动词","cn":"同意；赞成","en":"If you assent to something, you agree to it or agree with it.","ex":{"en":"I assented to the request of the American publishers to write this book","cn":"我同意了美国出版商的要求，答应写这本书。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"approval or agreement from someone who has authority","cn":"同意﹐赞成"},{"en":"to agree to a suggestion, idea etc after considering it carefully 〔","cn":"经审慎考虑后〕同意﹐赞成"}]},"vocab":{"pos":"v n","senses":[{"en":"Assent means agreement. If you nod your head in assent , you agree to something or you assent to it. You can assent in the same contexts as agree, but you'll seem a bit more serious."}]},"collocations":{"phrases":["ADJ. common, general, universal Medicine is, by common assent, a good profession. There was general assent about his achievements. | royal T","VERB + ASSENT give sth, grant The government gave their assent to the project. | withhold | meet with, obtain, receive | express, grunt, ind","PREP. in ~ She smiled in assent. | with/without sb's ~ The raising of taxes without the assent of Parliament was declared illegal.","PHRASES a murmur/nod of assent The suggestion was greeted with a murmur of assent."]},"media":{"uk":"media/ldoce/hwd/bre/9/assent_v0205.mp3","us":"media/ldoce/hwd/ame/4/ascent.mp3"},"examples":[{"en":"There were murmurs of both assent and dissent from the crowd.","cn":"人群议论纷纷，赞成和反对的都有。"},{"en":"Nobody would assent to the terms they proposed.","cn":"谁也不会同意他们提出的条件。"}],"oxford":{"phon":"əˈsent","pos":"noun","senses":[{"en":"official agreement to or approval of something","cn":"同意；赞成","ex":{"en":"The director has given her assent to the proposals.","cn":"负责人已表示同意提案。"}},{"en":"to agree to a request, an idea or a suggestion","cn":"同意，赞成（要求、想法或建议）","ex":{"en":"Nobody would assent to the terms they proposed.","cn":"谁也不会同意他们提出的条件。"},"pos":"verb"}]}},"assassinate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"行刺;暗杀","en":"When someone important is assassinated, they are murdered as a political act.","ex":{"en":"Would the USA be radically different today if Kennedy had not been assassinated?","cn":"如果肯尼迪没有被暗杀，今天的美国会有根本性的不同吗？"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone die","cn":""},{"en":"to deliberately kill someone – used when talking about this as a crime","cn":""},{"en":"to kill someone without intending to – used when talking about this as a crime","cn":""}]},"collocations":{"phrases":["VERB + ASSASSINATE attempt to, try to | plan to, plot to He was executed in 1887 for plotting to assassinate the tsar.","PHRASES an attempt/a plot to assassinate sb"]},"media":{"uk":"media/ldoce/hwd/bre/5/assassinate0205.mp3","us":"media/ldoce/hwd/ame/0/assassinate.mp3"},"examples":[{"en":"The president survived a number of assassination attempts.","cn":"总统在数次暗杀企图中幸免于难。"},{"en":"the assassination of John F. Kennedy","cn":"暗杀约翰 ·F· 肯尼迪"}],"oxford":{"phon":"əˈsæsɪneɪt","pos":"verb","senses":[{"en":"to murder an important or famous person, especially for political reasons","cn":"（尤为政治目的）暗杀，行刺","ex":{"en":"a plot to assassinate the president","cn":"刺杀总统的阴谋"}}]}},"aspirin":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"阿司匹林","en":"Aspirin is a mild drug which reduces pain and fever."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a substance used for treating illness","cn":""},{"en":"a small piece of medicine that you swallow","cn":""},{"en":"a small piece of solid medicine","cn":""}]},"collocations":{"phrases":["ADJ. soluble","QUANT. dose","VERB + ASPIRIN take She took an aspirin and went to bed. | dissolve Dissolve two aspirin in water.","ASPIRIN + VERB dissolve Aspirin dissolves quickly."]},"media":{"uk":"media/ldoce/hwd/bre/3/aspirin0205.mp3","us":"media/ldoce/hwd/ame/8/aspirin.mp3"},"examples":[{"en":"Take two aspirin(s) for a headache.","cn":"头痛服两片阿司匹林。"},{"en":"Do you have any aspirin?","cn":"你有阿司匹林吗？"}],"oxford":{"phon":"ˈæsprɪn","pos":"noun","senses":[{"en":"a drug used to reduce pain, high temperature and inflammation","cn":"阿司匹林（镇痛解热消炎药）","ex":{"en":"Do you have any aspirin?","cn":"你有阿司匹林吗？"}}]}},"asthma":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"气喘；哮喘","en":"Asthma is a lung condition which causes difficulty in breathing."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a medical condition that causes difficulties in breathing","cn":"哮喘"}]},"vocab":{"pos":"n","senses":[{"en":"Asthma is a respiratory condition that involves allergies and your lungs: people with asthma have trouble breathing at times."}]},"collocations":{"phrases":["ADJ. severe | acute, chronic | bronchial","VERB + ASTHMA have, suffer from | treat","ASTHMA + NOUN attack | sufferer •"]},"media":{"uk":"media/ldoce/hwd/bre/f/asthma0205.mp3","us":"media/ldoce/hwd/ame/0/asthma.mp3"},"examples":[{"en":"a severe asthma attack","cn":"哮喘严重发作"}],"oxford":{"phon":"ˈæsmə","pos":"noun","senses":[{"en":"a medical condition of the chest that makes breathing difficult","cn":"哮病；哮喘","ex":{"en":"a severe asthma attack","cn":"哮喘严重发作"}}]}},"ascent":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"攀登;上升;升高","en":"An ascent is an upward journey, especially when you are walking or climbing.","ex":{"en":"In 1955 he led the first ascent of Kangchenjunga, the world's third highest mountain.","cn":"他于1955年带队首攀世界第三高峰——干城章嘉峰。"}},{"pos":"N-COUNT 可数名词","cn":"上坡路；上坡","en":"An ascent is an upward slope or path, especially when you are walking or climbing.","ex":{"en":"It was a tough course over a gradual ascent before the big climb of Bluebell Hill.","cn":"在爬崎岖的蓝钟山之前有一段很难走的上行缓坡路。"}},{"pos":"N-COUNT 可数名词","cn":"垂直上升","en":"An ascent is an upward, vertical movement.","ex":{"en":"Burke pushed the button and the elevator began its slow ascent.","cn":"伯克按下按钮，电梯开始缓缓上升。"}},{"pos":"N-SING 单数名词","cn":"（地位、职位的）升高，提高","en":"The ascent of a person to a more important or successful position is the process of reaching this position.","ex":{"en":"His own career continues its inexorable ascent","cn":"他事业的上升势头锐不可当。"}},{"pos":"N-SING 单数名词","cn":"（某些宗教中的）升天","en":"In some religions, when someone goes to heaven, you can refer to their ascent to heaven.","ex":{"en":"...Elijah's ascent to heaven in a chariot of fire.","cn":"以利亚乘着烈火熊熊的战车升天了"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to move up towards the top of a wall, mountain, tree etc, using your hands and feet","cn":""},{"en":"to climb to the top of something very high, especially something that is very difficult or dangerous to climb","cn":""},{"en":"to climb in an awkward way or with difficulty, but moving fairly quickly","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If you are moving in an upward direction, that's an ascent , like your quick ascent from new group member last year to president this year."}]},"collocations":{"phrases":["ADJ. gradual, slow","VERB + ASCENT make The climbers made their ascent of the mountain without oxygen.","PREP. ~ from the ascent from the valley | ~ to their ascent to the summit 2 upward path/slope","ADJ. steep | long","VERB + ASCENT climb climbing the steep ascent on to the plateau | to a steep ascent to the village 3 becoming more important or powerful","ADJ. rapid | gradual | ~ to her rapid ascent to power"]},"media":{"uk":"media/ldoce/hwd/bre/5/ascent_las3_br.mp3","us":"media/ldoce/hwd/ame/4/ascent.mp3"},"examples":[{"en":"At the other side of the valley was a steep ascent to the top of the hill.","cn":"山谷的那边是直达山顶的陡坡。"},{"en":"The cart began its gradual ascent up the hill.","cn":"运货马车开始缓缓上山。"}],"oxford":{"phon":"əˈsent","pos":"noun","senses":[{"en":"the act of climbing or moving up; a journey that goes up something","cn":"上升；升高；登高","g":"[countable, usually singular]","ex":{"en":"the first ascent of Mount Everest","cn":"首次攀登珠穆朗玛峰"}},{"en":"a path or slope that goes up something","cn":"上坡路；上坡","g":"[countable, usually singular]","ex":{"en":"At the other side of the valley was a steep ascent to the top of the hill.","cn":"山谷的那边是直达山顶的陡坡。"}},{"en":"the process of moving forward to a better position or of making progress","cn":"前进；提高；进步","g":"[uncountable]","lab":"formal","ex":{"en":"man’s ascent to civilization","cn":"人类向文明的进化"}}]}},"assault":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"猛攻;强攻","en":"An assault by an army is a strong attack made on an area held by the enemy.","ex":{"en":"The rebels are poised for a new assault on the government garrisons","cn":"叛军准备好要对政府驻军发起新一轮的猛攻。"}},{"pos":"ADJ 形容词","cn":"（武器）用于战争的，军用的","en":"Assault weapons such as rifles are intended for soldiers to use in battle rather than for purposes such as hunting.","ex":{"en":"...a high-powered assault rifle.","cn":"大火力军用步枪"}},{"pos":"N-VAR 可变名词","cn":"人身攻击；殴打；（身体）侵犯","en":"An assault on a person is a physical attack on them.","ex":{"en":"The attack is one of a series of savage sexual assaults on women in the university area","cn":"这次袭击是在大学校园内发生的一系列针对女性的野蛮性侵犯事件中的一起。"}},{"pos":"VERB 动词","cn":"袭击；殴打","en":"To assault someone means to physically attack them.","ex":{"en":"The gang assaulted him with iron bars","cn":"这伙人用铁棍殴打他。"}},{"pos":"N-COUNT 可数名词","cn":"严厉抨击;强烈批评","en":"An assault on someone's beliefs is a strong criticism of them.","ex":{"en":"He leveled a verbal assault against his Democratic opponents.","cn":"他猛烈抨击其民主党对手。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the crime of physically attacking someone","cn":"侵犯人身（罪）﹐殴击他人身体（罪）"},{"en":"the crime of attacking and robbing someone in a public place","cn":""},{"en":"the crime of deliberately killing someone","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"An assault is an attack. Getting punched, yelled at, or bombed are all types of assault ."}]},"collocations":{"phrases":["ADV. badly, brutally, savagely, seriously, violently | indecently, physically, sexually, verbally"]},"media":{"uk":"media/ldoce/hwd/bre/4/assault_las3_br.mp3","us":"media/ldoce/hwd/ame/1/assault1.mp3"},"examples":[{"en":"Four women have been sexually assaulted in the area recently.","cn":"近来这个地区有四名妇女遭到强奸猥亵。"},{"en":"The paper's assault on the president was totally unjustified.","cn":"这份报纸对总统的攻击纯属无稽之谈。"}],"oxford":{"phon":"əˈsɔːlt","pos":"noun","senses":[{"en":"the crime of attacking somebody physically","cn":"侵犯他人身体（罪）；侵犯人身罪","g":"[uncountable, countable]","lab":"British English","ex":{"en":"Both men were charged with assault.","cn":"两人均被控侵犯他人身体罪。"}},{"en":"the act of attacking a building, an area, etc. in order to take control of it","cn":"攻击；突击；袭击","g":"[countable]","ex":{"en":"An assault on the capital was launched in the early hours of the morning.","cn":"凌晨时分向首都发起了攻击。"}},{"en":"the act of trying to achieve something that is difficult or dangerous","cn":"（向困难或危险事物发起的）冲击","g":"[countable]","ex":{"en":"The government has mounted a new assault on unemployment.","cn":"政府向失业发起新的攻势。"}},{"en":"an act of criticizing somebody/something severely","cn":"抨击","g":"[countable]","ex":{"en":"The suggested closures came under assault from all parties.","cn":"关闭机构的建议受到各方严厉批评。"}},{"en":"an act that threatens to harm somebody physically, whether or not actual harm is done","cn":"威胁要对某人造成身体伤害的行为，无论是否造成了实际伤害","g":"[countable, uncountable]","lab":"law"},{"en":"to attack somebody violently, especially when this is a crime","cn":"猛烈攻击，袭击，侵犯（尤指构成罪）","ex":{"en":"He has been charged with assaulting a police officer.","cn":"他被控袭击警察。"},"pos":"verb"},{"en":"to affect your senses in a way that is very unpleasant or uncomfortable","cn":"使（感官）难受","lab":"formal","ex":{"en":"Loud rock music assaulted our ears.","cn":"喧闹的摇滚乐直往我们耳朵里钻。"},"pos":"verb"}]}},"astute":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"精明的；敏锐的","en":"If you describe someone as astute, you think they show an understanding of behaviour and situations, and are skilful at using this knowledge to their own advantage.","ex":{"en":"She was politically astute","cn":"她很有政治头脑。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"intelligent in a practical way, and able to use your intelligence to get advantages for yourself","cn":""},{"en":"a shrewd person is good at deciding what people, situations etc are really like, so that it is difficult to deceive them - use this especially about people who are successful in business","cn":""},{"en":"someone who is astute easily understands why people behave in a particular way, why a situation is happening etc, without anyone having to tell them","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Someone who is astute is clever and has good judgment. The kid running around with a bucket stuck on his head? Not so astute ."}]},"collocations":{"phrases":["VERBS be","ADV. very | financially, politically"]},"media":{"uk":"media/ldoce/hwd/bre/b/astute0205.mp3","us":"media/ldoce/hwd/ame/1/astute.mp3"},"examples":[{"en":"It was an astute move to sell the shares then.","cn":"那时出售股份是精明之举。"},{"en":"an astute businessman/politician/observer","cn":"精明的商人；狡猾的政客；敏锐的观察家"}],"oxford":{"phon":"əˈstjuːt","pos":"adjective","senses":[{"en":"very clever and quick at seeing what to do in a particular situation, especially how to get an advantage","cn":"精明的；狡猾的","ex":{"en":"an astute businessman/politician/observer","cn":"精明的商人；狡猾的政客；敏锐的观察家"}}]}},"astonishment":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"惊讶;惊奇;惊愕","en":"Astonishment is a feeling of great surprise.","ex":{"en":"I spotted a shooting star which, to my astonishment, was bright green in colour","cn":"我看见一颗流星，使我大为惊奇的是，它居然是鲜亮的绿色。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a feeling of great surprise, especially because something has happened that you almost cannot believe","cn":""},{"en":"a feeling of great surprise, especially at something you have seen or something someone has told you","cn":""},{"en":"complete surprise","cn":"惊异﹐惊讶"}]},"vocab":{"pos":"n","senses":[{"en":"Astonishment is what you feel when you're extremely surprised. If a cat stood up and recited the Preamble to the Constitution, you’d stare in astonishment ."}]},"collocations":{"phrases":["ADJ. great | absolute, utter | mild an air of mild astonishment | blank a look of blank astonishment","VERB + ASTONISHMENT express | hide She could not hide her astonishment.","PREP. in ~ She gazed at him in astonishment. | to sb's ~ Then, to my great astonishment, he started to cry. | with ~ Everyone gasped with as","PHRASES a cry/gasp/look of astonishment"]},"media":{"uk":"media/ldoce/hwd/bre/e/astonishment0205.mp3","us":"media/ldoce/hwd/ame/a/astonishment.mp3"},"examples":[{"en":"To my utter astonishment, she remembered my name.","cn":"她竟记得我的名字，使我万分惊讶。"},{"en":"He stared in astonishment at the stranger.","cn":"他惊愕地盯着那陌生人。"}],"oxford":{"phon":"əˈstɒnɪʃmənt","pos":"noun","senses":[{"en":"a feeling of very great surprise","cn":"大为惊奇；惊诧","ex":{"en":"To my utter astonishment, she remembered my name.","cn":"她竟记得我的名字，使我万分惊讶。"}}]}},"asia":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the world's largest continent (= one of the seven main areas of land ) , which includes the countries of the Middle East and the countries between the Ural Mountains and the Pacific Ocean, such as India, China, Japan, and part of Russia","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/p028-000001768.mp3","us":"media/ldoce/hwd/ame/8/p028-000001768.mp3"},"oxford":{"phon":"ˈeɪʒə","pos":"noun","senses":[{"en":"the largest continent","cn":"亚洲（最大的洲）"}]}},"ashes":{"lemma":"ash","media":{"uk":"media/ldoce/hwd/bre/b/p028-000001761.mp3","us":"media/ldoce/hwd/ame/7/ashes__the_.mp3"}}});
